      "springs": [],
      "story_big": "אחד ממסלולי הכביש המזוהים ביותר עם רכיבת אופנועים בישראל: מתחילים מול הים, מטפסים אל קו הרכס, פוגשים כביש גבול היסטורי ומסיימים בעמק החולה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־תחנת דלק גשר הזיו, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור גליל מערבי ועליון: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־אגמון החולה, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nמערת קשת, פארק אדמית — הגליל המערבי, גאולוגיה מודרנית: מערת קשת אינה מערה סגורה אלא שריד של תקרת מערה גדולה שהתמוטטה. קשת הסלע שנותרה תלויה מעל נחל בצת הפכה לאחד מסמלי הגליל המערבי. מהמצוק אפשר להסביר לקבוצה כיצד מי גשם ממיסים לאורך זמן את סלע הגיר, יוצרים חללים, ולבסוף מותירים חלון ענק אל הים והרי הגליל.\n\nמצודת יחיעם — התקופה הצלבנית; 1265; 1948: ראשית המבצר מיוחסת לתקופה הצלבנית. בשנת 1265 החריב אותו הסולטאן הממלוכי ביברס, ובמאה ה־18 חיזק אותו שליט הגליל דאהר אל־עומר. במלחמת העצמאות הפך המקום לעמדת הגנה של קיבוץ יחיעם. אפשר לחבר כאן בין שלוש תקופות: צלבנים, שליטים מקומיים והמאבק על הדרך ליישובי הגליל ב־1948.\n\nמצודת כ״ח — משטרת המנדט; אפריל–מאי 1948: המצודה היא אחת ממצודות טגארט שנבנו בימי המנדט הבריטי. באביב 1948 נערכו במקום שלושה ניסיונות כיבוש של הפלמ״ח. השם מצודת כ״ח מנציח 28 לוחמים שנפלו בקרבות נבי יושע. התצפית לעמק החולה מסבירה היטב מדוע מי ששלט במצודה שלט גם בצומת הדרכים שמתחתיה.\n\nאגמון החולה — ייבוש החולה 1951–1958; הצפה מחדש בשנות ה־90: עמק החולה היה במשך אלפי שנים מערכת של אגם וביצות. בשנות ה־50 יובש רוב השטח כדי להרחיב חקלאות ולצמצם מלריה, אך הנזק האקולוגי והקרקע השוקעת הובילו בהמשך לשיקום חלקי ולהצפת אגמון החולה. כיום זהו צומת נדידה עולמי לציפורים, ובעונות המעבר אפשר לראות להקות ענק של עגורים.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים.",
