      "story_big": "טיול כביש עם עצירות תוכן חזקות: הר מירון, מצודת ביריה, סמטאות צפת וסיום במושבה הוותיקה ראש פינה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־צומת מירון, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור גליל עליון: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ראש פינה, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nמצודת ביריה — מרץ 1946: פרשת ביריה הייתה אחד המאבקים הסמליים נגד מדיניות המנדט. לאחר שהבריטים עצרו את אנשי היישוב ופינו את הנקודה במרץ 1946, אלפי בני נוער ואנשי היישוב עלו להר והקימו אותה מחדש. הבריטים פינו שוב, והציבור חזר פעם נוספת. לבסוף הותרה נוכחות יהודית קבועה במקום.\n\nמצפור נוף יער ביריה — מרץ 1946: פרשת ביריה הייתה אחד המאבקים הסמליים נגד מדיניות המנדט. לאחר שהבריטים עצרו את אנשי היישוב ופינו את הנקודה במרץ 1946, אלפי בני נוער ואנשי היישוב עלו להר והקימו אותה מחדש. הבריטים פינו שוב, והציבור חזר פעם נוספת. לבסוף הותרה נוכחות יהודית קבועה במקום.\n\nהעיר העתיקה צפת — המאה ה־16; רעידת האדמה של 1837: צפת הייתה במאה ה־16 מרכז עולמי של קבלה, הלכה ודפוס עברי. כאן פעלו רבי יוסף קארו, מחבר שולחן ערוך, והמקובל האר״י. העיר נפגעה קשות ברעידות אדמה, ובמיוחד ברעידה של 1837. הסמטאות והבתים המדורגים מספרים על עיר הררית שנבנתה, נהרסה ושבה לחיים שוב ושוב.\n\nאתר השחזור ראש פינה — 1878 ו־1882: עוד לפני העלייה הראשונה נעשה כאן ניסיון התיישבות בשם גיא אוני בשנת 1878. בשנת 1882 קמה המושבה ראש פינה, והיא הפכה לאחת ממושבות העלייה הראשונה. בתי האבן, בית הפקידות ונוף עמק החולה מאפשרים לספר על החלוצים, על תמיכת הברון רוטשילד ועל המעבר מחקלאות מסורתית למושבה מתוכננת.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. רוב היום מתאים לקצב תיור, עם אפשרות לשלב עצירות ארוכות. גם במסלול רגוע יש להישמר מכבישים משניים צרים.",
