      "story_big": "מסלול גובה של הרי געש כבויים, יער אודם, כפרים דרוזיים ומקורות מים. בחורף הוא יכול להפוך קר, ערפילי ואף מושלג.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־קצרין, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור רמת הגולן: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־קריית שמונה, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nהר בנטל — געשיות הגולן; מלחמת יום הכיפורים 1973: בנטל הוא חרוט געשי כבוי, חלק מרצף הרי הגעש של צפון הגולן. שכבות הבזלת והלוע מספרים על עבר גאולוגי אלים. מן הפסגה רואים את עמק קוניטרה ואת מרחבי סוריה, ובקרבת מקום התרחשו קרבות עמק הבכא במלחמת יום הכיפורים ב־1973.\n\nברכת רם — אגם טבעי בשקע געשי: ברכת רם היא אגם טבעי בצפון הגולן. מקובל להסביר אותו כשקע הקשור לפעילות הגעשית באזור, אף שהמחקר דן בפרטי היווצרותו. סביב האגם התפתחה חקלאות דרוזית של תפוחים ודובדבנים, ולכן הנוף משלב גאולוגיה, חקלאות ותרבות מקומית.\n\nשמורת הבניאס — פולחן האל פאן; התקופות ההלניסטית והרומית: שמו הקדום של המקום היה פניאס, על שם האל היווני פאן. סביב המערה והמעיין הוקמו מקדשים, ובהמשך התפתחה עיר רומית וביזנטית. המים הזורמים כאן הם ממקורות הירדן. חשוב לומר לקבוצה שהבניאס הוא אתר לצפייה והליכה; הרחצה בשמורה אינה חלק מהביקור הרגיל.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים. עליות וירידות משמעותיות, שינויי טמפרטורה וצל שמותיר אספלט לח. בלימה מוקדמת והילוך מתאים עדיפים על כניסה מהירה לפנייה.",
