          "story_long": "סיפור קרב קשה ממלחמת יום הכיפורים, שממחיש את הטופוגרפיה של דרום הרמה.\n\nבפתיחת מלחמת יום הכיפורים הותקף המוצב הקטן בתל סאקי בידי כוחות סוריים עדיפים. לוחמים פצועים הסתתרו בבונקר וניסו להחזיק מעמד עד החילוץ. הסיפור ממחיש כמה קטן היה המרחק בין עמדות התצפית לבין הצירים שעליהם נעו השריון והחי״ר.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
