          "era": "המרד הגדול; שנת 67 לספירה",
          "story_long": "עיר עתיקה, מצוקי נשרים ומפל; סיפור התנגדות בתקופה הרומית.\n\nגמלא הייתה עיר יהודית בנויה על שלוחה תלולה הדומה לגמל. בזמן המרד הגדול ברומאים היא נצורה ונכבשה בשנת 67 לספירה. יוסף בן מתתיהו תיאר את הקרב. לצד הסיפור ההיסטורי, מצוקי גמלא הם אזור קינון חשוב לעופות דורסים.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
