      "story_big": "מתחילים מתחת לפני הים, מטפסים אל מצוקי דרום הגולן, עוברים בין תצפיות לכנרת ומסיימים באתר העתיק גמלא ובקצרין.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־צמח, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור דרום ומרכז הגולן: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־קצרין, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nחמת גדר — מרחצאות רומיים מן המאות ה־2–4 לספירה: המעיינות החמים של חמת גדר משכו מבקרים כבר בעת העתיקה. הרומאים בנו כאן מתחם מרחצאות גדול בעמק הירמוך, סמוך לעיר גדרה הקדומה. המעיינות, שרידי המרחצאות ומסילת הרכבת הישנה מספרים יחד על אתר נופש שהיה גם צומת תחבורה אזורי.\n\nאנדרטת תל סאקי — 6–7 באוקטובר 1973: בפתיחת מלחמת יום הכיפורים הותקף המוצב הקטן בתל סאקי בידי כוחות סוריים עדיפים. לוחמים פצועים הסתתרו בבונקר וניסו להחזיק מעמד עד החילוץ. הסיפור ממחיש כמה קטן היה המרחק בין עמדות התצפית לבין הצירים שעליהם נעו השריון והחי״ר.\n\nשמורת גמלא — המרד הגדול; שנת 67 לספירה: גמלא הייתה עיר יהודית בנויה על שלוחה תלולה הדומה לגמל. בזמן המרד הגדול ברומאים היא נצורה ונכבשה בשנת 67 לספירה. יוסף בן מתתיהו תיאר את הקרב. לצד הסיפור ההיסטורי, מצוקי גמלא הם אזור קינון חשוב לעופות דורסים.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים.",
