          "story_long": "כפר דייגים עתיק ואתר מרכזי במסורת הנוצרית.\n\nכפר נחום היה יישוב דייגים ומסחר על חוף הכנרת. הוא מרכזי במסורת הנוצרית ומזוהה עם פעילותו של ישו בגליל. שרידי בית הכנסת והבתים העתיקים מאפשרים לדבר גם על חיי יום־יום בעיירה גלילית בתקופה הרומית והביזנטית.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
