          "story_long": "שרידי מנזר ביזנטי במזרח הכנרת.\n\nבכורסי נחשף מנזר ביזנטי גדול, המזוהה במסורת הנוצרית עם נס החזירים. הפסיפסים, הכנסייה ומיקום האתר מול הכנרת ממחישים את התפתחות אתרי הצליינות בארץ בתקופה הביזנטית.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
