          "story_long": "הפסקה נעימה מול המים והרי הגליל.\n\nמומלץ להחנות רק במקום מסודר, להתרחק משפת הכביש ולהגדיר מראש את זמן העצירה. בקבוצה גדולה מודיעים חמש דקות לפני היציאה כדי למנוע התפזרות.",
