          "era": "נוסדה ב־1910",
          "story_long": "הקבוצה הראשונה וסיפור ראשית ההתיישבות הקיבוצית.\n\nדגניה א׳ נוסדה בשנת 1910 ונחשבת ל״אם הקבוצות״. כאן התפתח דגם הקבוצה השיתופית שהשפיע על התנועה הקיבוצית. בקרבות 1948 נעצר באזור גם טור שריון סורי, והטנק המוצב בדגניה הפך לסמל של הקרב.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
