      "story_big": "מסלול קלאסי שמתאים גם להרכבה: מים כמעט לאורך כל היום, אתרי מורשת, תצפיות והפסקות אוכל נוחות.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־טבריה, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור כנרת: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־טבריה, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nכפר נחום — התקופות הרומית והביזנטית: כפר נחום היה יישוב דייגים ומסחר על חוף הכנרת. הוא מרכזי במסורת הנוצרית ומזוהה עם פעילותו של ישו בגליל. שרידי בית הכנסת והבתים העתיקים מאפשרים לדבר גם על חיי יום־יום בעיירה גלילית בתקופה הרומית והביזנטית.\n\nכורסי — מנזר ביזנטי מן המאות ה־5–6: בכורסי נחשף מנזר ביזנטי גדול, המזוהה במסורת הנוצרית עם נס החזירים. הפסיפסים, הכנסייה ומיקום האתר מול הכנרת ממחישים את התפתחות אתרי הצליינות בארץ בתקופה הביזנטית.\n\nדגניה א׳ — נוסדה ב־1910: דגניה א׳ נוסדה בשנת 1910 ונחשבת ל״אם הקבוצות״. כאן התפתח דגם הקבוצה השיתופית שהשפיע על התנועה הקיבוצית. בקרבות 1948 נעצר באזור גם טור שריון סורי, והטנק המוצב בדגניה הפך לסמל של הקרב.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. כבישים אזוריים בקצב אחיד, אך עדיין קיימים צמתים חקלאיים, טרקטורים ופניות שאינן צפויות מרחוק.",
