      "springs": [],
      "story_big": "שילוב של כביש 721, רכס הכרמל, כפרים דרוזיים ותצפית מהמוחרקה. מסלול קצר אך עשיר בפניות ובשינויי גובה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־עתלית, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור כרמל ורמות מנשה: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־יקנעם, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nתחנת דלק עתלית — מחנה מעפילים 1939–1948: מחנה המעפילים בעתלית שימש את שלטונות המנדט לכליאת מעפילים שנתפסו בדרכם לארץ. באוקטובר 1945 פרץ הפלמ״ח למחנה ושחרר יותר ממאתיים עצורים. הקרונות, הצריפים וגדרות התיל הופכים את סיפור ההעפלה למוחשי.\n\nמנזר המוחרקה — מסורת אליהו הנביא: המוחרקה מזוהה במסורת עם העימות בין אליהו לנביאי הבעל. המנזר הכרמליתי והמרפסת הגבוהה משקיפים אל עמק יזרעאל, הגלבוע והגליל. זהו מקום שבו הסיפור המקראי והטופוגרפיה מתחברים בצורה ברורה.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים. עליות וירידות משמעותיות, שינויי טמפרטורה וצל שמותיר אספלט לח. בלימה מוקדמת והילוך מתאים עדיפים על כניסה מהירה לפנייה.",
