          "story_long": "קיבוץ ברמות מנשה ונקודת מנוחה לפני המשך הפיתולים.\n\nלמוביל הקבוצה: זו נקודה טובה לספירת רוכבים, בדיקת טווח דלק, שתייה והחלטה אם לקצר את המסלול. אין להניח שכל תחנה פתוחה בכל שעה; מאמתים בבוקר היציאה.",
