          "fuel": false,
          "era": "קורסי הפיקוד של ההגנה, משנות ה־30",
          "story_long": "מקום המזוהה עם הכשרת מפקדי ההגנה והפלמ״ח.\n\nג׳וערה שימשה בסיס אימונים וקורסי מפקדים של ארגון ההגנה. רבים ממפקדי צה״ל הראשונים עברו כאן הכשרה. המבנה והעמקים סביבו מאפשרים לספר על המעבר מארגוני המחתרות לצבא סדיר.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
