          "story_long": "יציאה נוחה לכל הכיוונים.\n\nתל מגידו שולט על מעבר ואדי ערה ועל דרך הים. הקרב שניהל פרעה תחותמס השלישי בשנת 1457 לפנה״ס נחשב לקרב הראשון בהיסטוריה שתיאורו המפורט השתמר. התל כולל שכבות רבות של ערים, שערים, ארמונות ומערכות מים. השם ארמגדון נגזר מהר מגידו.\n\nלמוביל הקבוצה: זו נקודה טובה לספירת רוכבים, בדיקת טווח דלק, שתייה והחלטה אם לקצר את המסלול. אין להניח שכל תחנה פתוחה בכל שעה; מאמתים בבוקר היציאה.",
