          "story_long": "הורדוס בנה כאן נמל מלאכותי אדיר; היום נשארו תיאטרון, חומות ונמל עתיק.\n\nהורדוס בנה בקיסריה עיר ונמל מפוארים וקרא להם לכבוד אוגוסטוס קיסר. נמל סבסטוס היה מפעל הנדסי עצום בתקופתו. בהמשך הייתה קיסריה בירת הפרובינקיה הרומית ומרכז מנהלי חשוב. התיאטרון, ההיפודרום והנמל ממחישים את קנה המידה.\n\nרעיון לסיפור לקבוצה: מתחילים במה שרואים בעיניים, מוסיפים תאריך או תקופה אחת, ומסיימים בשאלה כיצד המקום שלט על הדרך או על המים. כך העצירה נשארת קצרה אך זכירה.",
