      "story_big": "טיול נינוח שמתאים להרכבה, עם עתיקות, מפרצים, מחנה מעפילים וכפר אמנים.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־קיסריה, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור חוף הכרמל: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־זכרון יעקב, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nנמל קיסריה — נמל הורדוס, סוף המאה ה־1 לפנה״ס: הורדוס בנה בקיסריה עיר ונמל מפוארים וקרא להם לכבוד אוגוסטוס קיסר. נמל סבסטוס היה מפעל הנדסי עצום בתקופתו. בהמשך הייתה קיסריה בירת הפרובינקיה הרומית ומרכז מנהלי חשוב. התיאטרון, ההיפודרום והנמל ממחישים את קנה המידה.\n\nמחנה המעפילים עתלית — מחנה מעפילים 1939–1948: מחנה המעפילים בעתלית שימש את שלטונות המנדט לכליאת מעפילים שנתפסו בדרכם לארץ. באוקטובר 1945 פרץ הפלמ״ח למחנה ושחרר יותר ממאתיים עצורים. הקרונות, הצריפים וגדרות התיל הופכים את סיפור ההעפלה למוחשי.\n\nעין הוד — כפר אמנים משנת 1953: לאחר מלחמת העצמאות יזם האמן מרסל ינקו הקמת כפר אמנים בעין הוד. בתי האבן הפכו לגלריות, סדנאות ומוזיאונים. זו עצירה מעניינת לדבר בה על שימור מבנים, אמנות והמורכבות של היסטוריית הכפר.\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 20% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. כביש שטוח יחסית עם רוחות צד, חול ליד הכניסות לחופים ועומס הולכי רגל ורכבים בסופי שבוע.",
