          "story_long": "מערה שהתגלתה בעבודות מחצבה ובה נטיפים וזקיפים בני אלפי שנים.\n\nמערת שורק התגלתה בשנת 1968 בעקבות פיצוץ במחצבה. הטיפות המחלחלות בסלע הגיר משקיעות מינרלים ויוצרות נטיפים וזקיפים בקצב איטי מאוד. המערה היא שיעור בזמן גאולוגי: מבנים קטנים יכולים לדרוש אלפי שנים.\n\nמומלץ להחנות רק במקום מסודר, להתרחק משפת הכביש ולהגדיר מראש את זמן העצירה. בקבוצה גדולה מודיעים חמש דקות לפני היציאה כדי למנוע התפזרות.",
