      "springs": [],
      "story_big": "מסלול ליבה לרוכבי כביש: טיפוס מהשפלה, כביש 395 המפותל, כפרים עתיקים, תצפיות וירידה דרך נס הרים.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־לטרון, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור הרי ירושלים: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־בית שמש, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nמנזר לטרון — קרבות מאי–יוני 1948: בלטרון נערכו כמה ניסיונות לכבוש את רכס המשטרה והמבצר כדי לפתוח את הדרך לירושלים הנצורה. הניסיונות נכשלו במחיר כבד, ולכן נסללה דרך בורמה העוקפת. התצפית על כביש 1 מסבירה עד כמה צר היה המסדרון לירושלים.\n\nדרך בורמה – מצפה הראל — יוני 1948: דרך בורמה הוכשרה בחשאי במהלך ההפוגה הראשונה ב־1948 כדי לעקוף את לטרון ולהעביר מזון, דלק וציוד לירושלים. בתחילה עברו קטעים ברגל ובג׳יפים, ובהמשך שופרה הדרך למשאיות. השם נלקח מן הדרך המפורסמת באסיה שנועדה לעקוף מצור.\n\nעין כרם — כפר עתיק ומסורת לידת יוחנן המטביל: עין כרם בנויה סביב מעיינות וטרסות. במסורת הנוצרית היא מקום הולדתו של יוחנן המטביל ומפגש מרים ואלישבע. בתי האבן, הכנסיות והבוסתנים מאפשרים לספר על כפר הררי שהתפתח סביב מקור מים.\n\nהסטף — חקלאות מדרגות קדומה: בסטף שוחזר נוף חקלאי של טרסות, בוסתנים ושני מעיינות. במשך דורות ניצלו תושבי ההר את המדרון באמצעות קירות תמך ותעלות השקיה. זו המחשה מצוינת לאופן שבו טכנולוגיה פשוטה אפשרה חקלאות בתנאי הר.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים. עליות וירידות משמעותיות, שינויי טמפרטורה וצל שמותיר אספלט לח. בלימה מוקדמת והילוך מתאים עדיפים על כניסה מהירה לפנייה.",
