      "story_big": "מסלול דרמטי מההר אל המקום הנמוך בעולם, בין מצוקים, אתרי מגילות, נווה מדבר ומצדה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־ירושלים, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור מדבר יהודה וים המלח: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ערד, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nגן לאומי קומראן — גילוי המגילות החל ב־1947: בשנת 1947 התגלו במערות קומראן המגילות הראשונות של מדבר יהודה. כתבי היד כוללים ספרי מקרא, פירושים וכתבים קהילתיים בני יותר מאלפיים שנה. האתר הסמוך מזוהה בדרך כלל עם קהילה יהודית שחיה כאן בתקופת הבית השני.\n\nעין גדי — נווה מדבר, עתיקות ומסורת מקראית: עין גדי היא נווה מדבר הניזון ממעיינות קבועים. המסורת המקראית קושרת את המקום לדוד ושאול. בבית הכנסת העתיק נמצא פסיפס מרשים מן התקופה הביזנטית. השילוב בין מים, מצוקים, יעלים והיסטוריה מסביר מדוע המקום היה מיושב שוב ושוב.\n\nמצדה מזרח — ארמונות הורדוס; המצור הרומי 73–74 לספירה: הורדוס בנה במצדה ארמונות ומחסנים בסוף המאה הראשונה לפנה״ס. לאחר חורבן הבית השני החזיקו במקום מורדים יהודים. הלגיון הרומי הטיל מצור ובנה סוללה, והמבצר נפל כנראה בשנת 73 או 74 לספירה. המחנות הרומיים עדיין נראים מן הפסגה.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nפרופיל הדרך המשוער: 54% כביש מהיר או בין־עירוני, 23% כביש מפותל, 18% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
