      "springs": [],
      "story_big": "אחד הכבישים היפים והמפורסמים בארץ, עם ירידה רצופה מהמדבר אל ים המלח. היופי אינו מסלול מרוצים: רוכבים בקצב שמאפשר לעצור בכל רגע.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־ערד, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור ערד ודרום ים המלח: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־נווה זוהר, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 50% כביש מפותל, 20% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים.",
