      "story_big": "כביש 40 מציג את הנגב בקצב משתנה: מרחבים פתוחים, קבר בן־גוריון, עיר נבטית ומצוק המכתש.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־באר שבע, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור הר הנגב: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־מצפה רמון, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nקבר בן־גוריון — עבר לשדה בוקר ב־1953: דוד בן־גוריון עבר לשדה בוקר בשנת 1953, מתוך אמונה שהנגב הוא מבחן מרכזי לעתיד המדינה. קברו וקבר פולה משקיפים אל נחל צין. זה מקום טוב לספר על מנהיג שבחר לסיים את חייו הרחק ממרכזי השלטון.\n\nעין עבדת — קניון נחל צין ומעיינות מדבריים: עין עבדת הוא קניון עמוק שנחתר בסלעי הקירטון של רמת עבדת. המעיינות הקבועים מאפשרים קיום צמחייה ובעלי חיים, ובהם יעלים. המראה הלבן של המצוקים מדגיש את הניגוד בין מדבר יבש לרצועת מים צרה.\n\nגן לאומי עבדת — עיר נבטית בדרך הבשמים: עבדת התפתחה כתחנת דרך נבטית על נתיב הבשמים שחיבר את דרום ערב לנמלי הים התיכון. בהמשך קמו בה מקדשים, כנסיות, גתות ומערכות חקלאות מדברית. היא מספרת כיצד מסחר בינלאומי יצר עיר משגשגת במדבר.\n\nמרכז המבקרים מכתש רמון — המכתש הגדול מסוגו בעולם: מכתש רמון הוא מכתש סחיפה שאורכו עשרות קילומטרים. מן המצוק אפשר לראות שכבות סלע, הרי געש קדומים ותופעות צבע. מרכז המבקרים משלב את הסיפור הגאולוגי עם סיפורו של האסטרונאוט אילן רמון.\n\nפרופיל הדרך המשוער: 45% כביש מהיר או בין־עירוני, 25% כביש מפותל, 25% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. קטעים ארוכים ופתוחים, רוחות צד, חום ושינויים חדים בטמפרטורה. המרחק בין שירותים גדול יותר והעייפות מצטברת גם כשהכביש נראה פשוט. כבישים אזוריים בקצב אחיד, אך עדיין קיימים צמתים חקלאיים, טרקטורים ופניות שאינן צפויות מרחוק.",
