      "springs": [],
      "story_big": "שדות, בתרונות לס, אתרי מורשת ויישובי הנגב המערבי. המסלול מיועד לימים שבהם האזור פתוח ובטוח לביקור.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־בית קמה, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור נגב מערבי: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־יד מרדכי, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nרוחמה – בתרונות — היישוב היהודי הראשון בנגב, 1911: רוחמה נוסדה בשנת 1911 ונחשבת לנקודת ההתיישבות היהודית הראשונה בנגב בעת החדשה. בארות המים, החווה והבתרונות שסביבה מספרים על ניסיון להיאחז בשטח צחיח עוד לפני הקמת יישובי חומה ומגדל.\n\nאתר הראשונים רוחמה — היישוב היהודי הראשון בנגב, 1911: רוחמה נוסדה בשנת 1911 ונחשבת לנקודת ההתיישבות היהודית הראשונה בנגב בעת החדשה. בארות המים, החווה והבתרונות שסביבה מספרים על ניסיון להיאחז בשטח צחיח עוד לפני הקמת יישובי חומה ומגדל.\n\nחץ שחור — פעולות התגמול, שנות ה־50: אתר חץ שחור מנציח את פעולות הצנחנים בשנות ה־50 ואת הלוחמים שנפלו. האתר משקיף על רצועת עזה ומאפשר לדבר על תקופה של חדירות, פעולות תגמול והתגבשות יחידות צה״ל הצעיר.\n\nיד מרדכי — קרב מאי 1948: קיבוץ יד מרדכי נקרא על שם מרדכי אנילביץ׳, מפקד מרד גטו ורשה. במאי 1948 בלמו מגיני הקיבוץ את הצבא המצרי במשך כמה ימים. העיכוב העניק זמן להתארגנות צפונה יותר והפך את הקרב לסמל.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
