      "story_big": "חול על הכביש, רוחות, עומס בחופים, אזור ביטחוני משתנה מדרום.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־אשקלון, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור חוף דרומי: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־4311, 42, 4, 3, 4, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nגשר עד הלום — 29 במאי 1948: בגשר עד הלום נעצר הטור המצרי שפלש צפונה במלחמת העצמאות. ב־29 במאי 1948 הופעלו לראשונה מטוסי הקרב של חיל האוויר הישראלי נגד הטור. השם מבטא את הנקודה הצפונית שאליה הגיע הצבא המצרי.\n\nבית ספר שדה שקמים / אתר ניצנים הישנה — קרב 7 ביוני 1948: ניצנים עמדה בפני התקפה מצרית קשה ונפלה ב־7 ביוני 1948. סיפור הקרב, הכניעה והוויכוח הציבורי שבא אחריה הוא מורכב. באתר ההנצחה אפשר לספר גם על הלוחמות והלוחמים ועל המחיר ששילמה הקהילה.\n\nגן לאומי אשקלון — עיר נמל קדומה ופלשתית: אשקלון הייתה אחת מערי פלשתים ומרכז נמל חשוב. העיר החליפה שליטים כנענים, פלשתים, רומאים, מוסלמים וצלבנים. הסוללה והשרידים בגן הלאומי מספרים על אלפי שנות התיישבות ליד מים וחוף.\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 20% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. כביש שטוח יחסית עם רוחות צד, חול ליד הכניסות לחופים ועומס הולכי רגל ורכבים בסופי שבוע.",
