      "story_big": "מסלול מעבר מהכרמל לכנרת דרך שתי ערים עתיקות שהיו מרכזי רוח ותרבות יהודית.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־יקנעם, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור עמק יזרעאל וגליל תחתון: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־טבריה, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nבית שערים — המאות ה־2–4 לספירה: בית שערים הפכה למרכז יהודי חשוב לאחר מרד בר־כוכבא. רבי יהודה הנשיא נקבר במקום, ובעקבותיו ביקשו יהודים מן הארץ ומן התפוצות להיקבר במערות הקבורה. כתובות ביוונית, ארמית ועברית מספרות על רשת קהילות רחבה.\n\nגן לאומי ציפורי — נמל עתיק מתקופות רבות: יפו הייתה שער ימי לארץ במשך אלפי שנים. היא מופיעה בסיפורי מצרים הקדומה, במקרא ובמסורות נוצריות. בשנת 1799 נכבשה בידי צבא נפוליאון. הנמל והסמטאות מאפשרים לספר על עיר שחיה ממסחר, עלייה לרגל וכיבושים.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. כבישים אזוריים בקצב אחיד, אך עדיין קיימים צמתים חקלאיים, טרקטורים ופניות שאינן צפויות מרחוק.",
