      "story_big": "טיול קהילתי ארוך שמתחיל ביציאה מהירה מן המרכז, עוצר לקפה ליד כפר ויתקין, מטפס לנצרת וממשיך דרך כביש 667 ותצפיות הגלבוע אל רחצה או מנוחה בסחנה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־דלק היובל, חולון, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור מרכז, עמק חפר, נצרת וגלבוע: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־גן השלושה וחזרה למרכז, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nכתף שאול — הר הגלבוע והמסורת המקראית: הר הגלבוע מזוהה עם הקרב שבו נהרגו שאול ובניו. מכאן אפשר לראות את עמק חרוד, עמק בית שאן והרי הגלעד. התצפית הופכת את הסיפור המקראי לגאוגרפיה מוחשית: ההר, העמק ונתיבי התנועה נמצאים כולם מול העיניים.\n\nגן השלושה — גן לאומי ומעיינות בטמפרטורה יציבה: גן השלושה, הסחנה, ניזון ממעיינות שמימיהם נעימים במשך כל השנה. לצד הבריכות הטבעיות נמצא אתר חומה ומגדל המשחזר את תל עמל, היישוב הראשון בשיטת חומה ומגדל שקם בדצמבר 1936. זו עצירה שמשלבת רחצה עם סיפור התיישבותי.\n\nפרופיל הדרך המשוער: 23% כביש מהיר או בין־עירוני, 43% כביש מפותל, 10% כביש אזורי ו־24% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים. רמזורים, נתיבי תחבורה ציבורית, קטנועים, פתיחת דלתות ושינויי נתיב. החלק העירוני אינו מקום לרכיבה קבוצתית צפופה.",
