      "springs": [],
      "story_big": "מסלול קהילתי טכני יחסית: כביש החוף הוא רק הגישה, והעניין האמיתי מתחיל בעלייה לבית אורן, במעברי הכרמל ובהמשך בגליל המערבי עד ארוחה בחורפיש.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־פז אשל, הרצליה, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור מרכז, כרמל וגליל מערבי: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־חורפיש וחזרה למרכז, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nפז מבוא עתלית — מחנה מעפילים 1939–1948: מחנה המעפילים בעתלית שימש את שלטונות המנדט לכליאת מעפילים שנתפסו בדרכם לארץ. באוקטובר 1945 פרץ הפלמ״ח למחנה ושחרר יותר ממאתיים עצורים. הקרונות, הצריפים וגדרות התיל הופכים את סיפור ההעפלה למוחשי.\n\nפרופיל הדרך המשוער: 37% כביש מהיר או בין־עירוני, 29% כביש מפותל, 24% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
