      "springs": [],
      "story_big": "מסלול קהילתי ארוך שמחבר את כבישי חבל לכיש עם הירידה מערד לים המלח. החלק המפותל הוא רק פרק אחד ביום ארוך, ולכן ניהול העייפות חשוב יותר מן הקצב.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־פז הסיירים, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור מרכז, לכיש, ערד וים המלח: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ערד וחזרה למרכז, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nפז עד הלום — 29 במאי 1948: בגשר עד הלום נעצר הטור המצרי שפלש צפונה במלחמת העצמאות. ב־29 במאי 1948 הופעלו לראשונה מטוסי הקרב של חיל האוויר הישראלי נגד הטור. השם מבטא את הנקודה הצפונית שאליה הגיע הצבא המצרי.\n\nתל לכיש — מסע סנחריב, 701 לפנה״ס: לכיש הייתה העיר השנייה בחשיבותה בממלכת יהודה. בשנת 701 לפנה״ס כבש אותה סנחריב מלך אשור. הוא תיעד את המצור בתבליטי ארמונו בנינוה. הסוללה, השער והחומות מחברים בין הארכאולוגיה בארץ לבין תיעוד אימפריאלי שנמצא בעיראק.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nפרופיל הדרך המשוער: 33% כביש מהיר או בין־עירוני, 48% כביש מפותל, 14% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים. כבישים אזוריים בקצב אחיד, אך עדיין קיימים צמתים חקלאיים, טרקטורים ופניות שאינן צפויות מרחוק.",
