      "springs": [],
      "story_big": "לולאה אמיתית שמתחילה ומסתיימת בירושלים: יורדים דרך מצפה יריחו, עוצרים בעין בוקק, מטפסים לערד וממשיכים דרך בית גוברין וכביש 38.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־ירושלים, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור ירושלים, ים המלח, ערד ושפלת יהודה: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ירושלים, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nגן לאומי בית גוברין — מרשה, אלעותרופוליס ומערות הפעמון: האזור כולל את מרשה ההלניסטית ואת בית גוברין הרומית, שנקראה אלעותרופוליס. סלע הקירטון הרך אפשר חציבת מערות קולומבריום, בתי בד, קברים ומערות פעמון. מתחת לגבעות מסתתרת כמעט עיר נוספת.\n\nפרופיל הדרך המשוער: 48% כביש מהיר או בין־עירוני, 39% כביש מפותל, 9% כביש אזורי ו־4% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. קטעים ארוכים ופתוחים, רוחות צד, חום ושינויים חדים בטמפרטורה. המרחק בין שירותים גדול יותר והעייפות מצטברת גם כשהכביש נראה פשוט. לב המסלול כולל רצף פניות ושינויי גובה. יש לצפות לפניות עיוורות, חצץ מקומי, רוכבי אופניים וכלי רכב החוצים מיישובים או חניונים.",
