      "story_big": "טיול שנבנה סביב מים ולא רק סביב פניות: מתחילים בסיפור גדעון ומעיין חרוד, עולים לתצפית גלבוע, יורדים לרחצה בסחנה ומסיימים בפארק המעיינות.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־צומת מגידו, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור עמק יזרעאל ועמק המעיינות: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־בית שאן, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nכתף שאול — הר הגלבוע והמסורת המקראית: הר הגלבוע מזוהה עם הקרב שבו נהרגו שאול ובניו. מכאן אפשר לראות את עמק חרוד, עמק בית שאן והרי הגלעד. התצפית הופכת את הסיפור המקראי לגאוגרפיה מוחשית: ההר, העמק ונתיבי התנועה נמצאים כולם מול העיניים.\n\nגן השלושה — גן לאומי ומעיינות בטמפרטורה יציבה: גן השלושה, הסחנה, ניזון ממעיינות שמימיהם נעימים במשך כל השנה. לצד הבריכות הטבעיות נמצא אתר חומה ומגדל המשחזר את תל עמל, היישוב הראשון בשיטת חומה ומגדל שקם בדצמבר 1936. זו עצירה שמשלבת רחצה עם סיפור התיישבותי.\n\nבית שאן — סקיתופוליס; רעידת האדמה של 749: בית שאן הרומית והביזנטית, סקיתופוליס, הייתה עיר מפוארת עם רחובות עמודים, תיאטרון ובתי מרחץ. רעידת אדמה חזקה בשנת 749 החריבה חלקים גדולים מן העיר. דווקא ההרס הפתאומי סייע לשמר פרטים רבים מתחת למפולות.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
