      "story_big": "מסלול נושאי שמוכיח כי מדבר יהודה הוא גם ארץ של מעיינות. עין מבוע פועם בתוך נחל פרת, עיינות צוקים הוא נווה מדבר נמוך, ועין גדי משלב מים, יעלים והיסטוריה.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־ירושלים, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור מדבר יהודה וצפון ים המלח: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ערד או ירושלים, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nעין גדי — נווה מדבר, עתיקות ומסורת מקראית: עין גדי היא נווה מדבר הניזון ממעיינות קבועים. המסורת המקראית קושרת את המקום לדוד ושאול. בבית הכנסת העתיק נמצא פסיפס מרשים מן התקופה הביזנטית. השילוב בין מים, מצוקים, יעלים והיסטוריה מסביר מדוע המקום היה מיושב שוב ושוב.\n\nערד — עיר כנענית באלף ה־3 לפנה״ס ומצודה מתקופת המלוכה: בתל ערד שתי שכבות מרכזיות: עיר כנענית גדולה מתקופת הברונזה הקדומה ומצודה ישראלית מאוחרת יותר. במצודה נחשף מקדש קטן עם מזבח וחדר פנימי. האתר מציג אלפי שנים של שליטה על דרכי הנגב.\n\nפרופיל הדרך המשוער: 54% כביש מהיר או בין־עירוני, 23% כביש מפותל, 18% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
