      "springs": [],
      "story_big": "טיול שמספר את הקרב על הדרך לירושלים. בכל עצירה מתקדם הסיפור: כישלון הכיבוש בלטרון, פתיחת דרך בורמה, השיירות בשער הגיא והקרב על הקסטל.\n\nהיום בנוי משלושה רבדים. תחילה קטע הגישה מ־לטרון, שבו שומרים את הקבוצה מסודרת ולא מבזבזים ריכוז. לאחר מכן מגיע לב המסלול באזור שפלת יהודה ומבואות ירושלים: כאן נמצאים הנוף, הפניות והעצירות שמצדיקות את היום. לבסוף מגיע קטע הסיום ב־ירושלים או אבו גוש, שבו העייפות כבר מורגשת ולכן מורידים קצב ומגדילים מרווחים.\n\nיד לשריון, לטרון — קרבות מאי–יוני 1948: בלטרון נערכו כמה ניסיונות לכבוש את רכס המשטרה והמבצר כדי לפתוח את הדרך לירושלים הנצורה. הניסיונות נכשלו במחיר כבד, ולכן נסללה דרך בורמה העוקפת. התצפית על כביש 1 מסבירה עד כמה צר היה המסדרון לירושלים.\n\nמצפה הראל – דרך בורמה — יוני 1948: דרך בורמה הוכשרה בחשאי במהלך ההפוגה הראשונה ב־1948 כדי לעקוף את לטרון ולהעביר מזון, דלק וציוד לירושלים. בתחילה עברו קטעים ברגל ובג׳יפים, ובהמשך שופרה הדרך למשאיות. השם נלקח מן הדרך המפורסמת באסיה שנועדה לעקוף מצור.\n\nחאן שער הגיא — שיירות לירושלים, 1948: שער הגיא היה צוואר הבקבוק של הדרך לירושלים. באביב 1948 הותקפו כאן שיירות אספקה, ושלדי המשוריינים הפכו לסמל. החאן המשוחזר מציג את סיפורי הנהגים, המלווים והמאבק לשמור על דרך פתוחה.\n\nהקסטל — קרב אפריל 1948: הקסטל שלט על הדרך לירושלים. הקרב עליו היה חלק ממבצע נחשון. עבד אל־קאדר אל־חוסייני נהרג באזור ב־8 באפריל 1948, ולמחרת נכבש ההר מחדש בידי הכוחות היהודיים. הסיסמה ״הטוראים ייסוגו והמפקדים יחפו״ מזוהה עם הקרב.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידה. המסלול משלב כבישים בין־עירוניים וכבישים אזוריים. יש לבדוק עבודות, חסימות ותנאי אחיזה בבוקר היציאה.",
