          "story_long": "המושבה למרגלות התבור היא פתיחה טבעית לסיפור ההתיישבות החקלאית בגליל.\n\nכפר תבור נוסדה בשנת 1901 ונקראה בתחילה מסחה. אנשי העלייה הראשונה ניסו לבנות כאן משק חקלאי בתנאים קשים, ובאזור פעלו גם אנשי ארגון השומר. הסיפור מתאים לפתיחת היום: לא רק מי סלל את הכביש, אלא מי ניסה לייצר סביבו חיים קבועים.\n\nלמוביל הקבוצה: לפני העצירה מודיעים היכן חונים, כמה זמן נשארים ומהי נקודת האיסוף. אין לעצור בשול צר, בפתח עיקול או במקום שמסתיר את הקבוצה מתנועה חולפת.",
