      "story_big": "מסלול שמתחיל בסיפור המושבות, מטפס אל אחד המבצרים הצלבניים השמורים בארץ, יורד בכביש נופי אל בקעת הירדן ומסיים במקום שבו נולד רעיון הקבוצה השיתופית המודרנית.\n\nהטיול יוצא מ־כפר תבור, עובר בלב גליל תחתון מזרחי ועמק הירדן ומסתיים ב־דגניה א׳. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nכפר תבור — 1901 והעלייה הראשונה: המושבה למרגלות התבור היא פתיחה טבעית לסיפור ההתיישבות החקלאית בגליל.\n\nכפר תבור נוסדה בשנת 1901 ונקראה בתחילה מסחה. אנשי העלייה הראשונה ניסו לבנות כאן משק חקלאי בתנאים קשים, ובאזור פעלו גם אנשי ארגון השומר. הסיפור מתאים לפתיחת היום: לא רק מי סלל את הכביש, אלא מי ניסה לייצר סביבו חיים קבועים.\n\nגן לאומי כוכב הירדן — המאה ה־12; התקופה הצלבנית: מבצר בלוואר שולט מגובה רב על עמק הירדן ועל דרכי המעבר מצפון לדרום.\n\nהמבצר נבנה במאה ה־12 בידי האבירים ההוספיטלרים. הוא מתוכנן כמבצר בתוך מבצר, מוקף חפיר עמוק החצוב בבזלת. התצפית ממחישה מדוע השליטה בגובה הייתה חשובה: מי שישב כאן ראה את הדרך לאורך הבקעה ואת המעברים מזרחה.\n\nגן לאומי בית שאן — 18 בינואר 749: רחובות העמודים והתיאטרון מספרים על עיר רומית־ביזנטית שנעצרה ברגע אחד.\n\nבית שאן, סקיתופוליס בתקופה הרומית, הייתה מרכז אזורי משגשג. רעידת האדמה של 18 בינואר 749 הפילה מבנים וגשרים, וחלק מהעיר נשאר קבור כך שהארכאולוגים יכלו לקרוא את הרחוב כמעט כמו צילום של אסון קדום.\n\nגשר הישנה — שנות ה־30; מאי 1948: בין שלושה גשרים ותחנת כוח ישנה מסתתר סיפור על חשמל, גבול ומלחמה.\n\nפנחס רוטנברג הקים באזור את מפעל החשמל בנהריים בשנות ה־30. במאי 1948 פוצצו מגיני גשר חלק מן הגשרים כדי לעכב כוחות אויב. זו עצירה שמחברת בין חזון תשתית אזרחי לבין רגע שבו אותה תשתית הפכה לקו הגנה.\n\nדגניה א׳ — 1910: סיום ליד הכנרת במקום המזוהה עם הקבוצה השיתופית הראשונה.\n\nדגניה נוסדה בשנת 1910 ונחשבת לקבוצה הראשונה. כאן אפשר לסכם את המעבר ממבצר צלבני ומפעל חשמל מודרני אל ניסוי חברתי־חקלאי שהשפיע על דמות ההתיישבות בארץ.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 35% כביש מפותל, 35% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
