          "story_long": "סיפור הקרב בתל חי והאופן שבו אירוע מקומי הפך למיתוס לאומי.\n\nב־1 במרץ 1920 נהרגו יוסף טרומפלדור וחבריו באירועי תל חי. פסל האריה השואג מנציח את הנופלים. מספרים את העובדות הידועות ומבדילים בין תיעוד לבין משפטים שהפכו למיתוס.\n\nלמוביל הקבוצה: לפני העצירה מודיעים היכן חונים, כמה זמן נשארים ומהי נקודת האיסוף. אין לעצור בשול צר, בפתח עיקול או במקום שמסתיר את הקבוצה מתנועה חולפת.",
