          "story_long": "יישוב המזוהה עם אנשי השומר ועם שמירת גבול הצפון.\n\nכפר גלעדי נוסד בשנת 1916 בידי אנשי השומר. הוא מאפשר לסיים את היום בסיפור על ארגון שמירה קטן שהפך לחלק מן הזיכרון הלאומי.\n\nלמוביל הקבוצה: לפני העצירה מודיעים היכן חונים, כמה זמן נשארים ומהי נקודת האיסוף. אין לעצור בשול צר, בפתח עיקול או במקום שמסתיר את הקבוצה מתנועה חולפת.",
