      "springs": [],
      "story_big": "טיול על קו הגובה שמעל עמק החולה, עם תצפיות אל החרמון וסיפורי הגבול, השומר ותל חי.\n\nהטיול יוצא מ־יסוד המעלה, עובר בלב אצבע הגליל והרי נפתלי ומסתיים ב־כפר גלעדי. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nיסוד המעלה — 1883: מושבה ותיקה בעמק החולה פותחת את היום לפני הטיפוס לרכס.\n\nיסוד המעלה נוסדה בשנת 1883. המתיישבים התמודדו עם ביצות, קדחת ובידוד, והסיפור שלהם מקדים את פרויקט ייבוש החולה בעשרות שנים.\n\nדרך נוף הרי נפתלי — דרך נוף מודרנית: דרך קק״ל מעל העמק מציגה את החולה כיחידה גאוגרפית אחת.\n\nהדרך נמשכת על המדרון המזרחי של הרי נפתלי. התצפית מאפשרת להסביר את המעבר בין בקעת החולה, רמת הגולן והחרמון. קק״ל מגדירה את הדרך כבסיסית לרכב, אך מצב המצע משתנה.\n\nמצפה עדי–מטולה — בדיקת מצב נדרשת: קטע קצר עם תצפיות אל מטולה ועמק עיון, רק אם הדרך עבירה ובטוחה.\n\nקק״ל מציינת שבדרך קיים קטע אבנים קצר העביר לרכב פרטי בזהירות. עבור אופנוע כביש זו אינה הבטחה: המוביל בודק בעיניים ומוותר ללא היסוס אם המצע רופף.\n\nמטולה — 1896 ואילך: רחוב המושבה מספר על יישוב שנוסד בקצה הצפוני של הארץ.\n\nמטולה נוסדה בשנת 1896. מיקומה הפך אותה שוב ושוב ליישוב גבול, וההיסטוריה המקומית מלמדת כיצד קו מדיני משנה חיי יום־יום, חקלאות ותחבורה.\n\nחצר תל חי והאריה השואג — 1 במרץ 1920: סיפור הקרב בתל חי והאופן שבו אירוע מקומי הפך למיתוס לאומי.\n\nב־1 במרץ 1920 נהרגו יוסף טרומפלדור וחבריו באירועי תל חי. פסל האריה השואג מנציח את הנופלים. מספרים את העובדות הידועות ומבדילים בין תיעוד לבין משפטים שהפכו למיתוס.\n\nכפר גלעדי — 1916: יישוב המזוהה עם אנשי השומר ועם שמירת גבול הצפון.\n\nכפר גלעדי נוסד בשנת 1916 בידי אנשי השומר. הוא מאפשר לסיים את היום בסיפור על ארגון שמירה קטן שהפך לחלק מן הזיכרון הלאומי.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 40% כביש מפותל, 35% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
