          "story_long": "מפרצים כחולים ושרידי יישוב לאורך דרך החוף העתיקה.\n\nאכזיב הייתה יישוב חוף במשך תקופות רבות. המפרצים הקטנים והסלעיים מסבירים מדוע נקודות עגינה ומעברים לאורך החוף היו חשובות עוד לפני כביש 4. רחצה רק במקום ובשעה המותרים.\n\nלמוביל הקבוצה: לפני העצירה מודיעים היכן חונים, כמה זמן נשארים ומהי נקודת האיסוף. אין לעצור בשול צר, בפתח עיקול או במקום שמסתיר את הקבוצה מתנועה חולפת.",
