      "story_big": "טיול שבו מקורות נחל נעמן, חומות עכו ומצוקי ראש הנקרה מספרים שלושה מפגשים שונים בין מים לאדם.\n\nהטיול יוצא מ־עין אפק, עובר בלב עמק עכו והגליל המערבי ומסתיים ב־ראש הנקרה. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nשמורת טבע עין אפק — היסטוריה סביבתית וטחנות קמח: שמורה שמחזירה חלק מנוף הביצות שאפיין את עמק עכו.\n\nעין אפק משמרת את מקורות נחל נעמן ואת אחד השרידים האחרונים של נופי הביצה במישור החוף הצפוני. טחנת הקמח מזכירה שמים היו גם כוח מניע וכלכלה, לא רק נוף.\n\nעכו העתיקה — התקופה הצלבנית; 1799: חומות, נמל ואולמות אבירים במקום שבו נפוליאון נעצר בשנת 1799.\n\nעכו הייתה עיר נמל מרכזית בתקופות רבות. בשנת 1799 לא הצליח נפוליאון לכבוש אותה. מתחת לעיר העות׳מאנית השתמרו אולמות מן התקופה הצלבנית, ולכן הליכה קצרה חושפת עיר על גבי עיר.\n\nלוחמי הגטאות — 1949 ואילך: קיבוץ שהקימו ניצולי שואה ובו מוסד זיכרון וחינוך.\n\nהקיבוץ נוסד בשנת 1949 בידי ניצולי שואה, ובהם לוחמי מחתרות ופרטיזנים. העצירה מאפשרת לחבר בין מרד, הישרדות ובניית חיים חדשים.\n\nגן לאומי אכזיב — העת העתיקה ועד ימינו: מפרצים כחולים ושרידי יישוב לאורך דרך החוף העתיקה.\n\nאכזיב הייתה יישוב חוף במשך תקופות רבות. המפרצים הקטנים והסלעיים מסבירים מדוע נקודות עגינה ומעברים לאורך החוף היו חשובות עוד לפני כביש 4. רחצה רק במקום ובשעה המותרים.\n\nראש הנקרה — תקופת המנדט; גאולוגיה חופית: הגלים חצבו נקרות בסלע, ורכבת מנדטורית חצתה כאן את הגבול.\n\nהנקרות נוצרו מפעולת גלים בסלע הקירטון. בתקופת המנדט נחפרה מנהרת רכבת כחלק מקו חיפה–ביירות–טריפולי. הגבול עצר את הרצף, והאתר הפך לסמל של קצה הדרך.\n\nפרופיל הדרך המשוער: 45% כביש מהיר או בין־עירוני, 5% כביש מפותל, 25% כביש אזורי ו־25% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
