      "springs": [],
      "story_big": "יום רכיבה שנבנה סביב כבישים אזוריים, יישובי חומה ומגדל, מסורת הכרמל וכפר אמנים.\n\nהטיול יוצא מ־בנימינה, עובר בלב רמות מנשה והכרמל ומסתיים ב־עין הוד. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nבנימינה — 1922: מושבה משנת 1922 שנקראה על שמו של הברון בנימין אדמונד דה רוטשילד.\n\nהיישוב מחבר בין מפעל המושבות, חקלאות ותשתית הרכבת. זהו מקום טוב להסביר כיצד תחנת רכבת וכבישים הפכו מושבה קטנה לצומת אזורי.\n\nגבעת ניל״י — 1915–1917: השם מנציח את מחתרת ניל״י שפעלה במלחמת העולם הראשונה.\n\nניל״י העבירה מידע לבריטים נגד השלטון העות׳מאני. סיפור אהרן ושרה אהרנסון, ריגול ומחיר אישי נותן עומק לעצירה קצרה.\n\nדליה ועין השופט — 1937–1939: שני קיבוצים שהוקמו בסוף שנות ה־30 במרחב רמות מנשה.\n\nהקמת יישובים בתקופת חומה ומגדל נועדה ליצור עובדות בשטח תוך התמודדות עם מגבלות ביטחון. הכבישים השקטים של היום עוברים בנוף שהיה פעם חזית התיישבותית.\n\nהמוחרקה — מסורת מקראית; המאה ה־19: מנזר הכרמליתים ותצפית רחבה לעמק יזרעאל.\n\nהמקום מזוהה במסורת עם המאבק של אליהו ונביאי הבעל. המבנה הנוכחי מן המאה ה־19, והתצפית ממחישה את הכרמל כקו פרשת מים וכרכס השולט על העמקים.\n\nעין הוד — שנות ה־50 ואילך: סיום בין גלריות ובתי אבן בכפר אמנים שהוקם בשנות ה־50.\n\nמרסל ינקו היה בין יוזמי כפר האמנים לאחר 1948. עין הוד מאפשרת לסיים את היום בדיון על אמנות, שימור ומורכבות היסטורית של מקום שעבר שינוי אוכלוסייה וזהות.\n\nפרופיל הדרך המשוער: 15% כביש מהיר או בין־עירוני, 45% כביש מפותל, 35% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
