          "story_long": "המנזר הטרפיסטי מוכר כ“מנזר השתקנים” ומספק פתיחה שקטה ליום.\n\nהקהילה הטרפיסטית התבססה במקום בסוף המאה ה־19. הנזירים שילבו תפילה, עבודה חקלאית ושגרת חיים קפדנית. מבקרים בכבוד ובודקים מראש אם החנות או הכנסייה פתוחות.\n\nלמוביל הקבוצה: לפני העצירה מודיעים היכן חונים, כמה זמן נשארים ומהי נקודת האיסוף. אין לעצור בשול צר, בפתח עיקול או במקום שמסתיר את הקבוצה מתנועה חולפת.",
