      "springs": [],
      "story_big": "מסלול של אדריכלות, נזירות ועלייה לרגל בין עמק איילון להרי ירושלים. הוא נותן למוביל סיפור רציף על קהילות שחיפשו שקט רוחני ליד דרכים מרכזיות.\n\nהטיול יוצא מ־לטרון, עובר בלב שפלת יהודה והרי ירושלים ומסתיים ב־אבו גוש. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nמנזר לטרון — סוף המאה ה־19: המנזר הטרפיסטי מוכר כ“מנזר השתקנים” ומספק פתיחה שקטה ליום.\n\nהקהילה הטרפיסטית התבססה במקום בסוף המאה ה־19. הנזירים שילבו תפילה, עבודה חקלאית ושגרת חיים קפדנית. מבקרים בכבוד ובודקים מראש אם החנות או הכנסייה פתוחות.\n\nמנזר בית ג׳מאל — המאה ה־19–20: מתחם כנסייתי על גבעה ליד בית שמש, המזוהה עם מסורות נוצריות קדומות.\n\nבמקום פועלים מוסדות נזיריים מן המסורת הסלזיאנית והקתולית. הכנסיות והנוף מאפשרים לדבר על הקשר בין מנזר, חקלאות ובידוד יחסי מן העיר.\n\nדיר ראפאת — שנות ה־20 של המאה ה־20: כנסייה ומנזר הצופים על שפלת יהודה.\n\nהאתר הוקם בתקופת המנדט ביוזמת הפטריארכיה הלטינית. הכתובת “שלום לך מרים” מופיעה בשפות רבות ומבטאת יעד של עלייה לרגל החוצה גבולות לשוניים.\n\nעין כרם — מסורות נוצריות; תקופות שונות: סמטאות, מעיין וכנסיות במקום המזוהה עם יוחנן המטביל.\n\nעין כרם הייתה כפר חקלאי והפכה מוקד עלייה לרגל. השילוב בין מעיין, טרסות וכנסיות מסביר מדוע מסורות דתיות נצמדות פעמים רבות למים ולנוף.\n\nאבו גוש — המאה ה־12: כנסייה מן המאה ה־12 וארוחה מסיימות את המסלול.\n\nהכנסייה הצלבנית באבו גוש בנויה מעל מעיין ומשמרת אדריכלות רומנסקית. המסורת קושרת את המקום לאמאוס. את היום מסיימים בארוחה, אך רוכבים אינם שותים אלכוהול לפני המשך הדרך.\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 40% כביש מפותל, 25% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
