      "springs": [],
      "story_big": "טיול קרוב למרכז שמראה כיצד מים ומעבר צר יצרו רצף של ערים, מבצרים ותשתיות מראש העין ועד מודיעין.\n\nהטיול יוצא מ־ראש העין, עובר בלב ראש העין, השפלה הצפונית ומודיעין ומסתיים ב־נאות קדומים. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nגן לאומי ירקון – תל אפק — העת העתיקה; התקופה העות׳מאנית והמנדט: תל השולט על מעבר אפק ועל מקורות הירקון.\n\nאפק הייתה נקודת מפתח בדרך הים. הורדוס הקים במקום עיר וקרא לה אנטיפטריס על שם אביו. המבצר העות׳מאני ומפעל המים הבריטי מדגימים כיצד אותו מקום שירת שליטים שונים בגלל מים ומעבר.\n\nבית הבטון ומקורות הירקון — ראשית המאה ה־20: מבנה תעשייתי מוקדם ליד מקורות המים של המרכז.\n\nבית הבטון נבנה בראשית המאה ה־20 ונחשב מן המבנים הראשונים בארץ שנבנו בבטון מזוין. המיקום ליד הירקון מדגים את המעבר מטחנות קמח לתשתית מודרנית.\n\nגן לאומי מגדל צדק — ימי הביניים ועד ימינו: מצודה על גבעה מעל מעבר ראש העין ונוף מחצבות ששוקם.\n\nהמצודה מוכרת גם כמגדל אפק. היא עברה גלגולים צלבניים, ממלוכיים ועות׳מאניים. סביבתה נפגעה ממחצבות, ותהליך השיקום הפך לחלק מן הסיפור המודרני של האתר.\n\nפתח תקווה – נקודת מורשת — 1878: עצירה קצרה ליד אתר מורשת חוקי ולא בתוך תנועה צפופה.\n\nפתח תקווה נוסדה בשנת 1878 ונקראה אם המושבות. הקרבה לירקון הייתה יתרון ומקור קושי בגלל ביצות ומחלות.\n\nנאות קדומים — המחצית השנייה של המאה ה־20: שמורה נופית שמחברת צמחים, חקלאות ומקורות יהודיים.\n\nהמקום פותח במאה ה־20 כדי להמחיש את נופי הצומח והחקלאות של המקרא והמשנה. זהו אתר פרשני ולא שמורת טבע “טבעית” בלבד, ולכן הסיפור הוא גם על הדרך שבה בונים זיכרון נופי.\n\nפרופיל הדרך המשוער: 30% כביש מהיר או בין־עירוני, 10% כביש מפותל, 45% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
