      "story_big": "מסלול עירוני־היסטורי שמספר ארבע באר שבע: עיר מקראית מתוכננת, עיר עות׳מאנית, זירת קרב בשנת 1917 ועיר מחוז ישראלית.\n\nהטיול יוצא מ־גן לאומי תל באר שבע, עובר בלב באר שבע וסביבתה ומסתיים ב־אנדרטת חטיבת הנגב. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nגן לאומי תל באר שבע — תקופת הברזל: תל שמציג עיר מתוכננת, שערים ומפעל מים מתקופת המקרא.\n\nהאתר משמר עיר מבוצרת מתקופת הברזל. הרחובות, המחסנים ומערכת המים מראים תכנון עירוני ולא רק אוסף בתים. התל נכלל באתרי המורשת העולמית של ערי המקרא.\n\nמצפה בית אשל — 1943–1948: אחד משלושת המצפים שהוקמו בנגב בשנת 1943.\n\nבית אשל, רביבים וגבולות נועדו לבחון אפשרות להתיישבות בנגב. במלחמת העצמאות עמד בית אשל תחת הפגזה ומצור, ותושביו החזיקו במקום עד כיבוש באר שבע.\n\nמתחם הקטר והעיר העתיקה — 1900–1917: תחנת הרכבת מספרת על הניסיון העות׳מאני לחבר את הנגב בזמן מלחמת העולם הראשונה.\n\nהעות׳מאנים סללו מסילה לבאר שבע כחלק ממאמץ צבאי ולוגיסטי. העיר העתיקה תוכננה כעיר מנהלית חדשה בתחילת המאה ה־20.\n\nמרכז אנז״ק — 31 באוקטובר 1917: סיפור הפרשים האוסטרלים והניו זילנדים שהסתערו על העיר ב־31 באוקטובר 1917.\n\nההסתערות על באר שבע הייתה חלק מן המערכה הבריטית נגד האימפריה העות׳מאנית. הכוחות נזקקו לבארות העיר, ולכן המהירות הייתה קריטית.\n\nאנדרטת חטיבת הנגב — שנות ה־60: יצירת הבטון של דני קרוון משקיפה על העיר ומנציחה את לוחמי הפלמ״ח.\n\nהאנדרטה נחנכה בשנות ה־60. צורותיה הפיסוליות יוצרות מעבר בין בונקרים, תעלות ומגדלים, ומספרות את הקרבות על הנגב בלי פסל מסורתי של לוחם.\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 5% כביש מפותל, 25% כביש אזורי ו־45% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
