      "springs": [],
      "story_big": "מסלול שמתחיל בקרב באר שבע של 1917, ממשיך בעקבות הדרך דרומה־מערבה ועובר דרך ניסויי ההתיישבות והעיר הנבטית־ביזנטית בניצנה.\n\nהטיול יוצא מ־באר שבע, עובר בלב צפון ומערב הנגב ומסתיים ב־ניצנה. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nמרכז אנז״ק באר שבע — 31 באוקטובר 1917: קרב 31 באוקטובר 1917 פותח את מסלול התנועה דרומה.\n\nהפרשים הקלים האוסטרלים הסתערו בשעות אחר הצהריים כדי לכבוש את באר שבע ואת בארותיה. ההצלחה פתחה את הדרך להמשך המערכה הבריטית בארץ.\n\nפארק גולדה — שיקום נופי מודרני: אגם מדברי במקום מחצבה משוקמת על נתיב אנז״ק.\n\nקק״ל שיקמה את המחצבה ופיתחה פארק סביב מים המגיעים משיטפונות וממערכת המרחצאות הסמוכה. זהו סיפור מודרני של שימוש מחדש בנוף פגוע.\n\nמצפה רביבים — 1943: אחד משלושת המצפים שעלו על הקרקע בשנת 1943.\n\nהמצפה בחן מים, חקלאות ואפשרות לקיום יישוב בנגב. המבקרים יכולים להבין מדוע ידע על קרקע ומים היה גם ידע אסטרטגי.\n\nשבטה – תצפית/ביקור לפי זמן — התקופות הנבטית והביזנטית: עיר נבטית־ביזנטית שמראה כיצד חקלאות התקיימה ללא מעיין קבוע.\n\nתושבי שבטה אספו מי נגר במערכת מתוחכמת של סכרים, תעלות ובורות. האתר מדגים שהמדבר אינו ריק, אלא מרחב שדורש ידע הנדסי וחברתי.\n\nגן לאומי ניצנה — התקופה הביזנטית; 1915–1917: עיר עתיקה ושרידי עיירה עות׳מאנית ליד הגבול.\n\nבניצנה שרדו כנסיות ומבנים ביזנטיים. לקראת מלחמת העולם הראשונה הקימו העות׳מאנים עיירה ותחנת רכבת. השכבות הרבות הופכות אותה לסיום מושלם ליום על נתיבי תנועה.\n\nפרופיל הדרך המשוער: 55% כביש מהיר או בין־עירוני, 10% כביש מפותל, 30% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
