      "springs": [],
      "story_big": "מסלול מעגלי סביב ערד שמביא את הקבוצה אל הצד המערבי והשקט יותר של מצדה, אל עיר מקראית בתל ערד ואל קו המעבר בין מדבר ליער.\n\nהטיול יוצא מ־ערד, עובר בלב מדבר יהודה ודרום הר חברון ומסתיים ב־ערד. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nמצפור מואב, ערד — אמנות ישראלית מודרנית: הפסל והמדבר פותחים את היום במבט מזרחה.\n\nהמצפור מדגים את ירידת רמת המדבר אל ים המלח. האמן יגאל תומרקין יצר במקום פסל סביבתי שמחבר אמנות לנוף פתוח.\n\nכפר הנוקדים — תיירות מדברית מודרנית: נקודת מנוחה בדרך למצדה, עם אפשרות לאוכל בתיאום.\n\nהמקום מציג גרסה תיירותית של אירוח מדברי. מספרים לקבוצה שמדובר באתר מסחרי ופרשני, לא “כפר בדואי עתיק”, ומכבדים את האנשים והתרבות בלי להשטיח אותם.\n\nגן לאומי מצדה – מערב — 73–74 לספירה: הגישה המערבית מביאה סמוך לסוללת המצור הרומית.\n\nאחרי המרד הגדול הקים הצבא הרומי מחנות וסוללה כדי להגיע אל פסגת מצדה. הסוללה היא עדות לעבודת הנדסה וללוגיסטיקה של מצור. סיפור ההתאבדות ההמונית נשען בעיקר על יוסף בן מתתיהו ויש להציגו בזהירות.\n\nגן לאומי תל ערד — האלף השלישי לפנה״ס; תקופת הברזל: עיר כנענית ומצודה מתקופת ממלכת יהודה באותו תל.\n\nבחלק התחתון נמצאת עיר כנענית מתוכננת, ובפסגה מצודה ישראלית ובה מקדש קטן ומפעל מים. השכבות ממחישות כיצד אותו מקום שימש מטרות שונות במשך אלפי שנים.\n\nיער יתיר — שנות ה־60 ואילך: היער הגדול על גבול האקלים הים־תיכוני והמדברי מסיים את המעגל.\n\nקק״ל נטעה את היער החל משנות ה־60. הוא משמש גם אתר מחקר על הקשר בין יער, פחמן ואקלים יבש. הדרך עשויה לכלול קטעים צרים ומטיילים.\n\nפרופיל הדרך המשוער: 15% כביש מהיר או בין־עירוני, 40% כביש מפותל, 40% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
