      "story_big": "מסלול גבול שמחבר עיר נבטית וביזנטית, תחנת רכבת עות׳מאנית, יישוב קטן בעזוז ונופי קירטון לבנים.\n\nהטיול יוצא מ־ניצנה, עובר בלב גבול מצרים ומערב הנגב ומסתיים ב־ניצנה. קטעי הקישור נועדו להביא את הקבוצה אל החלק המעניין; בהם שומרים מרווחים, נמנעים מעקיפות מיותרות ומגיעים לעצירה הראשונה עם ריכוז מלא.\n\nגן לאומי ניצנה — התקופה הביזנטית; 1915–1917: שרידים נבטיים־ביזנטיים לצד עיירה ותחנת רכבת עות׳מאנית.\n\nניצנה הייתה מרכז על דרך המדבר. בתקופה הביזנטית פעלו בה כנסיות, ובמלחמת העולם הראשונה בנו העות׳מאנים תחנת רכבת ומבנים מנהליים.\n\nתחנת הרכבת העות׳מאנית ניצנה — מלחמת העולם הראשונה: שרידי מסילה ומבנים מספרים על לוגיסטיקה במדבר.\n\nהמסילה נועדה לתמוך בצבא העות׳מאני בחזית סיני. במדבר, רכבת הייתה דרך להעביר מים, תחמושת ואנשים בכמות שאי אפשר היה להשיג בשיירות גמלים בלבד.\n\nעזוז ובארותיים — שנות ה־50 ואילך: יישוב קטן ליד בארות היסטוריות ומרחב גבול.\n\nהשם בארותיים מזכיר את חשיבות מקורות המים. לאחר קום המדינה הוקמו באזור נקודות משמר ויישוב כדי ליצור נוכחות לאורך הגבול.\n\nחמוקי ניצנה — גאולוגיה מדברית: גבעות קירטון לבנות שעוצבו ברוח ובמים.\n\nהסלע הרך מקבל צורות מעוגלות ומבהיקות. זהו אתר רגיש; מחנים במקום מותר והולכים ברגל בלי לחרוץ את הסלע באופנוע.\n\nפתחת ניצנה וקדש ברנע — מסורת מקראית; התיישבות מודרנית: חקלאות מודרנית ליד מרחב המזוהה במסורות מקראיות.\n\nהשם קדש ברנע קשור למסורות נדודי בני ישראל, אך הזיהוי המדויק של האתר המקראי שנוי במחלוקת. כיום האזור מדגים חקלאות מדברית, יישובי גבול ותלות בתשתיות מים.\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 10% כביש מפותל, 50% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד, לא מדידת GPS ולא הבטחה למצב האספלט ביום הרכיבה.",
