      "springs": [],
      "story_big": "יום שמחבר בין בזלת קדומה לקרבות 1973: רכיבה על רמה געשית, תצפיות רחבות וסיפורים על עמידה תחת לחץ.\n\nהטיול מתחיל ב־קצרין, עובר דרך רמת הגולן ומסתיים ב־קצרין. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nקצרין העתיקה — המאות הרביעית–השישית: קצרין העתיקה משמרת בתי מגורים ובית כנסת הבנויים באבן בזלת. היא מאפשרת לספר כיצד חיו חקלאים יהודים בגולן בתקופת המשנה והתלמוד, בתוך נוף שבו הקרקע הגעשית הפכה כרמים ומטעים לאפשריים.\n\n\n\nתל סאקי — 6–7 באוקטובר 1973: בתל סאקי נלכדו לוחמים ישראלים בבונקר קטן במהלך הימים הראשונים של מלחמת יום הכיפורים. הסיפור אינו רק על קרב, אלא על אחוות לוחמים, מחסור במים וקבלת החלטות כאשר התמונה כולה אינה ברורה.\n\n\n\nהר בנטל — געשיות קדומה; 1973: בנטל הוא חלק מקו התילים הגעשיים של הגולן. מן הפסגה אפשר לראות את גבול סוריה, את קוניטרה ואת המרחב שבו ניהלו טנקים קרבות ב־1973. זו נקודה טובה להסביר כיצד הטופוגרפיה מכתיבה שדה ראייה ונתיבי תנועה.\n\n\n\nאנדרטת עוז 77 בעמק הבכא — אוקטובר 1973: בקרב עמק הבכא עמד כוח ישראלי קטן יחסית מול מאמץ שריון סורי גדול. הסיפור מדגיש את חשיבות קווי הרכס, התצפית וההתמדה, אך גם את המחיר הכבד ששילמו הלוחמים משני הצדדים.\n\n\n\nצומת ווסט — נקודת דרך מודרנית: כאן עוצרים לספירה, שתייה ותדלוק. אחרי יום עמוס בסיפורים, הסכנה היא ירידת ריכוז דווקא בדרך חזרה; לכן מגדירים קצב רגוע ומרווחים גדולים.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 45% כביש מפותל, 30% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. כבישי הרמה פתוחים ומהירים למראה, אך שינויי מזג אוויר, רוחות צד, בקר וכלים חקלאיים מחייבים מרווח ביטחון.",
