      "story_big": "טיול מים כמעט לכל היום: נביעות הירדן, פלגים קרים, חורשת אלונים עתיקה וסיפור על גבולות, טחנות קמח והתיישבות.\n\nהטיול מתחיל ב־קריית שמונה, עובר דרך אצבע הגליל ומקורות הירדן ומסתיים ב־כפר בלום. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nשמורת טבע תל דן — התקופה הכנענית והמקראית: דן משלבת נביעה עוצמתית עם תל עתיק. אפשר לספר על שער העיר הכנעני, על העיר דן המקראית ועל הקשר הישיר בין מים, מסחר, פולחן ושליטה בדרך צפונה.\n\n\n\nגן לאומי חורשת טל — אלוני תבור עתיקים; אתר נופש מודרני: חורשת טל ידועה באלונים עתיקים ובפלגי מים שמקורם בנחל דן. זהו מקום לעצירה ארוכה, שכשוך או רחצה רק במתחמים המורשים, וארוחה קלה בצל.\n\n\n\nשמורת טבע בניאס – מתחם המעיינות — התקופה ההלניסטית ועד ימי הביניים: השם בניאס משמר את שמו של האל פאן. במקום התפתח מרכז פולחן הלניסטי ובהמשך יישוב חשוב. המים זורמים כל השנה, אך אינם הזמנה לרחצה; הערך כאן הוא נוף, הליכה וסיפור.\n\n\n\nשמורת טבע נחל שניר — מערכת מקורות הירדן: נחל שניר הוא הארוך במקורות הירדן. בחלק מן המסלולים יש קטעי שכשוך מוסדרים בעונה ובכפוף להנחיות, ולכן בודקים את המסלול והכללים לפני הכניסה.\n\n\n\nכפר בלום — התיישבות בעמק החולה, המאה ה־20: כפר בלום מסכם את היום בסיפור ההתיישבות בעמק החולה ואת המעבר מביצות, מלריה ובידוד למרחב חקלאי ותיירותי. זו נקודה טובה לארוחה ולבדיקת עייפות לפני החזרה.\n\n\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 20% כביש מפותל, 45% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
