      "story_big": "יום היסטורי שמתחיל במושבת העלייה הראשונה, חוזר אל חצור הכנענית ומגיע אל סיפור ייבוש החולה והשיקום האקולוגי.\n\nהטיול מתחיל ב־ראש פינה, עובר דרך גליל עליון ועמק החולה ומסתיים ב־ראש פינה. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nאתר השחזור בראש פינה — 1882 ואילך: ראש פינה נוסדה מחדש בשנת 1882 והייתה לאחת ממושבות העלייה הראשונה. בתי הפקידות, בית הכנסת והרחובות המדורגים מאפשרים לספר על חקלאות קשה, תמיכת הברון רוטשילד והניסיון לבנות כלכלה עצמאית.\n\n\n\nנחל ראש פינה – חניון המושבה — מעיינות ובוסתנים: הנחל מזכיר שהמושבה קמה במקום שבו ניתן היה להשיג מים. המעיינות מזינים מערכת טבע רגישה; הכניסה למים אסורה, והעצירה נועדה לתצפית ולסיפור על גיא אוני וראש פינה.\n\n\n\nגן לאומי תל חצור — האלף השני והראשון לפנה״ס: חצור שלטה על דרכים בין מצרים, סוריה ומסופוטמיה. הארמון הכנעני ומפעל המים ממחישים עיר עשירה ומאורגנת. אפשר לספר על אזכוריה במקרא ועל הוויכוח הארכאולוגי סביב חורבנה.\n\n\n\nיסוד המעלה — 1883 ואילך: יסוד המעלה קמה בשנת 1883. המתיישבים נאבקו במלריה, הצפות ובידוד, ובכל זאת בנו חקלאות וקהילה. זהו מעבר טוב מן העיר הקדומה אל החלוציות המודרנית.\n\n\n\nשמורת טבע החולה — שמורה מ־1964; ייבוש בשנות ה־50: ייבוש החולה נועד להוסיף קרקע חקלאית ולהילחם במלריה, אך יצר גם נזק אקולוגי. השמורה משמרת חלק מן המערכת המקורית ומספרת כיצד תפיסות סביבתיות השתנו. הכניסה למים אסורה.\n\n\n\nפרופיל הדרך המשוער: 30% כביש מהיר או בין־עירוני, 25% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
