      "springs": [],
      "story_big": "מסלול קצר יחסית במרחק אך עשיר בסיפור: כפר יהודי מבזלת, מרכזי עלייה לרגל, דייגים, בתי כנסת ודרכי מסחר סביב הכנרת.\n\nהטיול מתחיל ב־צומת עמיעד, עובר דרך צפון הכנרת ורמת כורזים ומסתיים ב־מגדלא. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nגן לאומי כורזים — המאות השלישית–השישית: כורזים הייתה כפר יהודי בתקופת המשנה והתלמוד. בית הכנסת הבזלתי, בתי הבד והמקווה מספרים על קהילה חקלאית שחיה מן הקרקע הגעשית. המקום מוזכר גם בברית החדשה ולכן מושך קהלים שונים.\n\n\n\nהר האושר — המסורת הנוצרית; הכנסייה מ־1938: הכנסייה המודרנית נבנתה בשנות ה־30 של המאה ה־20. מן הגן רואים את אזור פעילותו של ישו לפי המסורת הנוצרית. זהו מקום לדבר על הדרך שבה נוף הופך לזיכרון דתי.\n\n\n\nכפר נחום — התקופה הרומית והביזנטית: כפר נחום היה יישוב יהודי חשוב. בית הכנסת המרשים נבנה מאבן גיר בהירה על יסודות בזלת, ומסורות נוצריות קושרות את המקום לפעילותו של ישו. החיבור בין דייג, מסחר ואמונה ניכר במיקום.\n\n\n\nטבחה — התקופה הביזנטית והעת החדשה: המעיינות בטבחה משכו יישוב וחקלאות עוד לפני שהמקום הפך מוקד עלייה לרגל. פסיפסי הכנסייה מזכירים כיצד סיפור דתי מתקבע באמנות ובמרחב.\n\n\n\nמגדלא — המאה הראשונה לספירה: מגדלא הייתה עיירת דייג ומסחר. גילוי בית הכנסת מן המאה הראשונה הוסיף פרק חשוב להבנת החיים היהודיים סביב הכנרת לפני חורבן הבית השני. מסיימים מול המים ובקצב רגוע.\n\n\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 25% כביש מפותל, 30% כביש אזורי ו־20% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
