      "story_big": "מסע בין שתי קהילות מיעוט בעלות זהות מובחנת: צ׳רקסים בכפר כמא ודרוזים סביב נבי שועייב, בית ג׳אן ופקיעין.\n\nהטיול מתחיל ב־כפר כמא, עובר דרך גליל תחתון ועליון ומסתיים ב־פקיעין. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nכפר כמא – מרכז המורשת הצ׳רקסית — התיישבות צ׳רקסית משנות ה־70 של המאה ה־19: הצ׳רקסים הגיעו לאזור בתקופה העות׳מאנית לאחר גירושם מן הקווקז. בכפר כמא נשמרו שפה, ריקוד, לבוש ומסורת צבאית. זהו סיפור על קהילה קטנה ששומרת זהות בתוך מדינה רב־תרבותית.\n\n\n\nנבי שועייב — מסורת דרוזית; האתר המודרני התפתח במאות האחרונות: נבי שועייב הוא האתר הקדוש המרכזי לעדה הדרוזית. מדי אפריל מתקיימת בו זיארה. בביקור מסבירים את הקשר בין יתרו, משה והמסורת הדרוזית, ונכנסים בכבוד ובהתאם לכללים.\n\n\n\nתצפית הר הארי ליד בית ג׳אן — הגליל העליון: בית ג׳אן שוכנת גבוה בהר מירון. התצפית ממחישה את הבידוד ההיסטורי של הכפרים ההרריים ואת היתרון הביטחוני והחקלאי של רום ההר.\n\n\n\nפקיעין העתיקה — יישוב רב־עדתי; מסורות עתיקות: פקיעין מזוהה עם רצף התיישבות של דרוזים, נוצרים, מוסלמים ויהודים. מסורת יהודית קושרת את המקום לרבי שמעון בר יוחאי. הסיפור המרכזי הוא חיים משותפים, לעיתים מורכבים, סביב מעיין וכיכר אחת.\n\n\n\nמרכז פקיעין — מסורת מקומית: מסיימים בארוחה דרוזית או קפה מקומי. לפני היציאה סופרים רוכבים ומזכירים שהקטע היורד מן הכפר דורש ריכוז מיוחד בגלל פניות, רכבים חונים ושינויי אחיזה.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 45% כביש מפותל, 25% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
