      "story_big": "מסלול שמתחיל בנמל צלבני, מטפס למבצרים בהרים ומסביר כיצד שלטו המצודות על דרכים, נחלים ואדמות חקלאיות.\n\nהטיול מתחיל ב־עכו העתיקה, עובר דרך גליל מערבי ומסתיים ב־מעלות־תרשיחא. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nהעיר העתיקה עכו — התקופה הצלבנית; 1291; 1799: עכו הייתה בירת הממלכה הצלבנית השנייה עד נפילתה ב־1291. בשנת 1799 עמדה בפני מצור נפוליאון. החומות והאולמות מאפשרים לספר כיצד נמל מסחרי הפך גם למכונת הגנה.\n\n\n\nגן לאומי מבצר יחיעם — התקופה הצלבנית; 1265; 1948: יחיעם מחבר בין צלבנים, הממלוכים ודאהר אל־עומר, ובהמשך בין המבצר לקיבוץ הנצור ב־1948. ממרומי המגדל רואים מדוע מצודה על רכס שולטת במרחב.\n\n\n\nמעיליא — ימי הביניים ועד ימינו: מעיליא שומרת מבנה כפר הררי צפוף. שרידי מבצר המלך מזכירים מערכת של אחוזות ומבצרים צלבניים, בעוד הכנסיות והבתים מספרים על רצף חיים מקומי.\n\n\n\nמצפה מונפור — המאה ה־13: המונפור היה מבצר של המסדר הטבטוני. הוא לא נועד להגן על גבול ממלכה אלא לשמש מרכז מנהלי ואוצר. מגיעים לתצפית בלבד; הירידה למבצר ארוכה ואינה חלק מטיול הכביש.\n\n\n\nמעלות־תרשיחא — עיר מאוחדת מ־1963: האיחוד בין מעלות לתרשיחא יוצר מקום שבו שוק, אוכל ותרבות נפגשים עם עיר פיתוח. זו עצירה מתאימה לסכם אלף שנות שינוי במרחב.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 40% כביש מפותל, 25% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
