      "springs": [],
      "story_big": "טיול רגוע בין בתי אבן טמפלריים, שדות העמק ותחנת רכבת שהייתה חלק מן המסילה החיג׳אזית.\n\nהטיול מתחיל ב־קריית טבעון, עובר דרך עמק יזרעאל וגליל תחתון מערבי ומסתיים ב־כפר יהושע. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nקריית טבעון – בית שערים מבחוץ — שנות ה־30 של המאה ה־20; העת העתיקה בסביבה: טבעון צמחה מאיחוד שכונות ויישובים. מיקומה ליד בית שערים, מקום מושב הסנהדרין וקברי יהודים מן העולם העתיק, מכניס את הקבוצה אל אזור שבו שכבות רבות יושבות זו על זו.\n\n\n\nבית לחם הגלילית — 1906: הטמפלרים הגרמנים הקימו כאן מושבה חקלאית בשנת 1906. הם הביאו שיטות בנייה וחקלאות מודרניות לתקופתם. אחרי מלחמת העולם השנייה השתנה היישוב, אך ציר הבתים נשמר.\n\n\n\nאלוני אבא — 1907; תקופת המנדט: אלוני אבא נוסדה כמושבה טמפלרית בשם ולדהיים. הכנסייה והבתים מספרים על קהילה גרמנית פרוטסטנטית ועל המהפכים שעברה הארץ במאה ה־20.\n\n\n\nתחנת רכבת העמק כפר יהושע — 1905: רכבת העמק החלה לפעול ב־1905 כחלק מרשת הרכבת החיג׳אזית. היא קישרה את חיפה לעמק ולסוריה, ונעה לאט עד שהפכה לחלק מן הפולקלור המקומי.\n\n\n\nרמת ישי — יישוב מודרני בעמק: כאן מסיימים יום איטי יחסית. היתרון הוא שאפשר לשוחח עם הקבוצה בלי למהר; החיסרון הוא שהכביש הביתה עמוס, ולכן לא נותנים לאווירה הרגועה להפוך לחוסר ריכוז.\n\n\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 15% כביש מפותל, 40% כביש אזורי ו־20% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
