      "story_big": "מסלול העוקב אחר מים שהניעו טחנות קמח, כפרים שהתפתחו סביב מעיינות וירידה מרהיבה אל הכנרת.\n\nהטיול מתחיל ב־כרמיאל, עובר דרך גליל תחתון ומזרחי ומסתיים ב־טבריה. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nכרמיאל — הוקמה ב־1964: כרמיאל נבנתה כעיר מתוכננת בשנות ה־60. היא ממוקמת על מעבר טבעי בין עכו לצפת, ולכן מתאימה לפתיחת יום ולסיפור קצר על פיתוח הגליל.\n\n\n\nפרוד — יישוב מודרני ליד דרך עתיקה: אזור פרוד יושב על קו מעבר בין הרי מירון לבקעות. בחורף ובאביב ניכרת זרימה עונתית, אך אין להניח שהמים מתאימים לרחצה.\n\n\n\nגן לאומי נחל צלמון — התקופה העות׳מאנית והעת החדשה: המים בנחל הפעילו בעבר טחנות קמח. בכל טחנה תורגמה נפילת מים לסיבוב אבן ריחיים. זו דוגמה לטכנולוגיה פשוטה ששינתה כלכלה מקומית. שכשוך רק אם מותר ובמקום המתאים.\n\n\n\nמג׳אר — יישוב רב־עדתי: מג׳אר היא דוגמה למרחב רב־עדתי בגליל. העצירה מתאימה לאוכל מקומי ולשיחה על זהויות, שירות ציבורי ומסורות החיות זו לצד זו.\n\n\n\nמצפור נוף כנרת ליד ארבל — גאולוגיה והיסטוריה: מכאן נראית הכנרת כאגן עמוק מתחת לרכסים. אפשר להסביר את השבר הסורי־אפריקאי ואת הסיבה לכך שהכבישים יורדים בפיתולים. ממשיכים לטבריה לארוחה.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 45% כביש מפותל, 25% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
