      "springs": [],
      "story_big": "מסלול בין אתרי מסורת נוצריים, עיר עתיקה, כפרי גליל והר תבור – עם סיום בתרבות הצ׳רקסית.\n\nהטיול מתחיל ב־הר הקפיצה, עובר דרך נצרת והגליל התחתון ומסתיים ב־כפר כמא. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nהר הקפיצה — מסורת נוצרית; נוף עמק יזרעאל: הר הקפיצה מזוהה במסורת עם אירוע מן הבשורה על פי לוקס. מעבר למסורת, התצפית מסבירה את מיקומה של נצרת בין רכסי הגליל לעמק יזרעאל.\n\n\n\nכנסיית הבשורה בנצרת — הכנסייה הנוכחית נחנכה ב־1969: הכנסייה המודרנית משלבת אמנות ממדינות רבות ונבנתה מעל מערה המזוהה במסורת עם בית מרים. זו נקודה לדבר על הדרך שבה אתר קדוש נבנה מחדש שוב ושוב לאורך מאות שנים.\n\n\n\nכפר כנא — התקופה הביזנטית ועד ימינו: כפר כנא הוא מוקד עלייה לרגל, אך גם יישוב חי וצפוף. הסיפור מאפשר להבחין בין מסורת דתית לבין מחקר היסטורי, בלי לבטל את חשיבות המקום למאמינים.\n\n\n\nהר תבור — קרבות מקראיים; כנסיות מודרניות: תבור בולט משום שהוא מתרומם לבדו מעל העמק. הוא מזוהה עם סיפור דבורה וברק ובמסורת הנוצרית עם ההשתנות. העלייה מפותלת וצרה; אוטובוסים ורכב מקומי מחייבים זהירות.\n\n\n\nכפר כמא — התיישבות צ׳רקסית במאה ה־19: הצ׳רקסים הגיעו לכפר כמא בשלהי התקופה העות׳מאנית. כאן אפשר לסיים בארוחה, לשמוע על שפה ומנהגים ולחבר בין מסע דתי למסע תרבותי.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 30% כביש מפותל, 25% כביש אזורי ו־25% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
