      "story_big": "יום היסטורי עמוק: מצור רומי ביודפת, עיר רב־תרבותית בציפורי, מערות מצוק בארבל ופסיפס בית כנסת על שפת הכנרת.\n\nהטיול מתחיל ב־יודפת, עובר דרך גליל תחתון וכנרת ומסתיים ב־חמת טבריה. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nתל יודפת — 67 לספירה: יוסף בן מתתיהו פיקד על הגנת יודפת בשנת 67. לאחר מצור קשה העיר נפלה והוא נכנע לרומאים. הסיפור הוא שער להבנת המרד הגדול ולשאלה כיצד נכתב זיכרון בידי מי שעבר צד.\n\n\n\nגן לאומי ציפורי — התקופה הרומית והביזנטית: ציפורי הייתה מרכז מנהלי ותרבותי. רבי יהודה הנשיא ישב בה בתקופה שבה נערכה המשנה. הפסיפסים מציגים תרבות עירונית שבה יהודים, רומאים ונוצרים חיו במרחב משותף.\n\n\n\nמצפור הארבל — ימי הבית השני ועד העת החדשה: הארבל שלט על דרך חשובה ליד הכנרת. המערות שימשו מסתור בזמנים שונים, והמצוק מאפשר להבין כיצד גובה וראות נותנים יתרון. נשארים במצפור ובשבילים המותרים.\n\n\n\nטבריה העתיקה — נוסדה סביב 20 לספירה: הורדוס אנטיפס ייסד את טבריה בראשית המאה הראשונה. בהמשך הפכה העיר למרכז יהודי חשוב, ובה נחתם התלמוד הירושלמי לפי המסורת המחקרית המקובלת.\n\n\n\nגן לאומי חמת טבריה — המאות השלישית–הרביעית: בית הכנסת בחמת טבריה מציג גלגל מזלות ודמות הליוס, עדות לשפה אמנותית מורכבת בחברה היהודית העתיקה. המעיינות משכו בני אדם מאז העת העתיקה, אך רחצה נעשית רק במתחמים מורשים.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 40% כביש מפותל, 25% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
