      "springs": [],
      "story_big": "טיול קרוב למרכז שמחבר תצפית, מרד החשמונאים, תל קדום ונוף תרבותי של חקלאות מקראית.\n\nהטיול מתחיל ב־מצפה מודיעין, עובר דרך חבל מודיעין ויער בן שמן ומסתיים ב־נאות קדומים. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nמצפה מודיעין — יער מודרני ומורשת האזור: המצפה משקיף אל השפלה וההרים. זו נקודת פתיחה להסביר מדוע האזור שימש מעבר בין מישור החוף לירושלים ומדוע המרד החשמונאי צמח בכפרים ההרריים.\n\n\n\nתל חדיד — תקופות הברזל, הפרסית וההלניסטית: חדיד נזכרת במקורות מתקופות שונות. מיקומה מעל הדרך נתן שליטה על תנועה ועל אדמות חקלאיות. התצפית מדגימה את הקשר בין תל, דרך ומים.\n\n\n\nקברות המכבים – אתר מסורת — מסורת מאוחרת; המאה השנייה לפנה״ס ברקע: חשוב לספר ביושר: השם “קברות המכבים” התקבע, אך אין ודאות שאלה קברי משפחת החשמונאים. דווקא הפער בין מסורת לממצא הופך את העצירה למעניינת.\n\n\n\nדרך היער המרכזית — דרך נוף מודרנית: זהו קטע איטי ולא טכני. עומדים על הרגליות רק אם צריך, לא מחליקים בכוונה ולא עוקפים רוכבי אופניים בצפיפות. אחרי גשם מוותרים אם הדרך בוצית.\n\n\n\nנאות קדומים — הוקם במאה ה־20 על בסיס מקורות קדומים: נאות קדומים מחבר טקסטים עתיקים אל גתות, בתי בד, בורות מים וצמחי ארץ ישראל. הסיום כאן נותן לקבוצה תוכן מעבר לרכיבה ויכול להפוך לביקור מודרך.\n\n\n\nפרופיל הדרך המשוער: 25% כביש מהיר או בין־עירוני, 15% כביש מפותל, 50% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
