      "springs": [],
      "story_big": "טיול אמנות ונוף שמחליף חלק מן האספלט בדרך יער כבושה, עם פסלים, תצפית לעמק שורק ומנזר על רכס.\n\nהטיול מתחיל ב־צומת שמשון, עובר דרך יער צרעה והשפלה ומסתיים ב־טל שחר. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nכניסה ליער צרעה — יער קק״ל מודרני: לפני הכניסה מסבירים לקבוצה: מרווחים גדולים, בלי עקיפות, בלי אבק מכוון ובלי סטייה לשבילים צדדיים. מי שאינו מרגיש בנוח יכול להגיע ישירות לנקודה הבאה באספלט.\n\n\n\nדרך הפסלים — פרויקט אמנות סביבתית: אמנים יצרו עבודות המתייחסות לנוף, לאבן ולסיפורים מקומיים. הרכיבה איטית ומאפשרת לבחור שתיים או שלוש יצירות לסיפור קצר במקום לנסות לעצור ליד כולן.\n\n\n\nמצפה צרעה — עמק שורק והרי יהודה: התצפית מסבירה את המבנה הטופוגרפי של האזור ואת הקשר בין דרכי הרוחב של עמק שורק לעלייה לירושלים.\n\n\n\nמנזר דיר ראפאת — נוסד ב־1927: דיר ראפאת הוקם לאחר רעידת האדמה של 1927 והוקדש למרים מלכת פלשתינה. כתובות “שלום לך מרים” בשפות רבות מדגישות את אופיו הבינלאומי של המקום.\n\n\n\nטל שחר — מושב מ־1948: מסיימים ביישוב או בעגלת קפה בסביבה. מנקים אבק מפנסים ומוודאים שאין אבן תקועה בבלמים לפני העלייה לכביש מהיר.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 10% כביש מפותל, 60% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
