      "story_big": "טיול שמראה מדוע השפלה מלאה תלים, מערות ומצודות: זו ארץ מעבר בין החוף להר, עשירה בגיר רך ונוחה לחציבה.\n\nהטיול מתחיל ב־צומת האלה, עובר דרך שפלת יהודה ומסתיים ב־בית גוברין. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nתל עזקה — תקופת הברזל: עזקה נזכרת במקרא בהקשר למסעות מלחמה ולסיפור דוד וגוליית באזור עמק האלה. מן התל רואים את המרחב שבו עברו צבאות בין פלשת ליהודה.\n\n\n\nדרך נוף פארק בריטניה — פיתוח קק״ל מודרני: הדרך עוברת בין חורש, טרסות ובוסתנים. הרכיבה איטית, והמטרה היא ליהנות מן המעבר בין רכסים ולא לצבור מהירות.\n\n\n\nמצפה משואה — שפלת יהודה: המצפה נמצא על קו פרשת מים מקומי. הוא מסביר כיצד האזור שימש “מסדרון” בין שתי יחידות נוף שונות.\n\n\n\nמערות לוזית — חציבה בתקופות קדומות: מערות הפעמון נוצרו כשחוצבים ירדו דרך פתח קטן והרחיבו את החלל כלפי מטה. האבן שימשה לבנייה, והחללים קיבלו בהמשך שימושים נוספים.\n\n\n\nגן לאומי בית גוברין — התקופה ההלניסטית עד הביזנטית: מרשה ובית גוברין מציגות אלפי שנות חציבה וחיים תת־קרקעיים. המערות שימשו מחסנים, בתי בד, קולומבריה וקברים. זהו סיום עשיר שדורש זמן ולא מתאים ל“רק צילום”.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 35% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
