      "springs": [],
      "story_big": "טיול שמעמיק מתחת לפני השטח: כפרים יהודיים, מחילות מסתור ומרד בר כוכבא בשנים 132–136 לספירה.\n\nהטיול מתחיל ב־צומת האלה, עובר דרך פארק עדולם ושפלת יהודה ומסתיים ב־בית גוברין. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nחורבת מדרס — תקופת הבית השני ומרד בר כוכבא: מדרס הייתה חלק ממרחב יישובים יהודיים בשפלה. מערכת המסתור הצרה מדגימה כיצד הוכנו חללים לתנועה, אגירה והסתתרות מול הצבא הרומי.\n\n\n\nחורבת עתרי — המאה הראשונה והשנייה לספירה: עתרי מציגה כפר שנפגע במרד הגדול וחזר להתקיים עד מרד בר כוכבא. מקוואות וכלי אבן מסייעים לזהות את האוכלוסייה היהודית.\n\n\n\nפארק עדולם — חקלאות קדומה: הנוף אינו “טבע פראי” בלבד; הוא תוצאה של אלפי שנות מרעה, חקלאות וחציבה. זו נקודה טובה להסביר מהו נוף תרבותי.\n\n\n\nתל עדולם – תצפית מהאזור המותר — מסורות מקראיות: עדולם נזכרת בסיפורי דוד. הזיהוי המדויק והגישה משתנים, ולכן מסתפקים בתצפית מן המקום המותר ולא מנסים לכבוש את התל באופנוע.\n\n\n\nגן לאומי בית גוברין — התקופה ההלניסטית–ביזנטית: בית גוברין מסכמת את היום בכך שהיא מראה שהמערות לא היו רק מסתור: הן היו תשתית כלכלית שלמה. מסיימים בארוחה באזור ולא ממהרים לחזור.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 20% כביש מפותל, 50% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
