      "story_big": "טיול קרוב לירושלים שמחבר כפר עתיק, אנדרטת נשיא, חורש, טרסות ושני אתרי מעיינות.\n\nהטיול מתחיל ב־עין כרם, עובר דרך מערב ירושלים ורכס שלמון־שורק ומסתיים ב־סטף. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nעין כרם — כפר קדום; מסורות נוצריות: עין כרם התפתחה סביב מעיין ובוסתנים. במסורת הנוצרית היא קשורה ליוחנן המטביל. היום היא שכונה, אך המבנה הכפרי עדיין מורגש.\n\n\n\nיד קנדי — נחנכה ב־1966: האנדרטה בנויה מ־51 עמודים המסמלים את מדינות ארצות הברית ומחוז קולומביה בעת הקמתה. המיקום הגבוה נבחר כדי להפוך את הזיכרון לחלק מן הנוף.\n\n\n\nחורבת סעדים — שרידים חקלאיים ומקודשים: החורבה והעצים מדגימים את הקשר בין מקום קדוש לשמירת חורש. לעיתים עצים שרדו דווקא משום שהיו ליד אתר מקודש.\n\n\n\nעין לבן — חקלאות טרסות עתיקה: המעיין סיפק מים לחקלאות מדרגות. הרחצה אינה שירות מציל ומצב המים משתנה; נכנסים רק אם מותר ובזהירות, בלי לקפוץ ובלי לזהם.\n\n\n\nסטף — שחזור חקלאות מסורתית: בסטף משוחזרת מערכת חקלאות בעל המבוססת על טרסות ומעיינות. אפשר להסביר כיצד מדרגות אבן מונעות סחף ושומרות קרקע. כניסה למים רק לפי השילוט.\n\n\n\nפרופיל הדרך המשוער: 15% כביש מהיר או בין־עירוני, 50% כביש מפותל, 25% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
