      "springs": [],
      "story_big": "מסלול קצר של רכסים וסיפורי תש״ח: קיבוץ ותיק, קרבות הדרך לירושלים, יישוב גבוה וירידה אל אוכל טוב באבו גוש.\n\nהטיול מתחיל ב־קריית ענבים, עובר דרך הרי ירושלים הצפוניים ומסתיים ב־אבו גוש. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nקריית ענבים — נוסד ב־1920: קריית ענבים הוקמה ב־1920 ונאבקה בתנאי הר קשים. במלחמת העצמאות שימשה בסיס לכוחות הראל. בית העלמין הצבאי מספר את מחיר הקרבות על הדרך לירושלים.\n\n\n\nמעלה החמישה — נוסד ב־1938: השם מנציח חמישה עובדים שנהרגו בשנת 1937. היישוב הוקם בתקופת חומה ומגדל וממחיש את המאבק על אחיזה ברכסים.\n\n\n\nהר אדר — משטרת הרדאר; 1948 ו־1967: “הרדאר” היה יעד חשוב בקרבות 1948 ושוב ב־1967. מן הגובה ניתן להבין את חשיבות השליטה על צירי הגישה לירושלים.\n\n\n\nנטף — הוקם ב־1982: נטף יושב בקצה דרך, מול נחל כפירה. הנסיעה אליו יפה אך דורשת סבלנות. השרפות שחוו הרי ירושלים מלמדות על פגיעות יערות, יישובים ורוחות.\n\n\n\nאבו גוש — יישוב עתיק; מנזרים מן התקופה הצלבנית: אבו גוש יושבת על הדרך ההיסטורית לירושלים. המנזרים, המסגד והמסעדות מספרים על מקום מעבר שהפך למוקד מפגש. מסיימים בלי אלכוהול ועם זמן להתאושש לפני הרכיבה.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 45% כביש מפותל, 20% כביש אזורי ו־15% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
