      "story_big": "טיול עירוני שמחליף פיתולים פתוחים בשכבות היסטוריה: אוניברסיטה, העיר העתיקה, גבול 1948, שכונות ראשונות ועמק כפרי.\n\nהטיול מתחיל ב־הר הצופים, עובר דרך ירושלים העירונית ומסתיים ב־עין כרם. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nהר הצופים — האוניברסיטה העברית נפתחה ב־1925: הר הצופים היה מובלעת ישראלית בין 1948 ל־1967. קמפוס האוניברסיטה והמרכז הרפואי הדסה מסמלים חזון מדעי ורפואי לצד סיפור גבול מורכב.\n\n\n\nהר הזיתים — בית קברות עתיק; מסורות יהודיות ונוצריות: הר הזיתים משקיף על הר הבית ועל עמק קדרון. בית הקברות היהודי משתרע מאות שנים, והכנסיות מציגות את חשיבות ההר במסורת הנוצרית.\n\n\n\nמתחם התחנה הראשונה — הרכבת לירושלים הגיעה ב־1892: המסילה מיפו לירושלים שינתה מסע של שעות רבות לרכבת איטית אך מהפכנית. התחנה מספרת על מודרניזציה בסוף התקופה העות׳מאנית.\n\n\n\nמשכנות שאננים וימין משה — 1860 ואילך: משכנות שאננים הוקמה ביוזמת משה מונטיפיורי. טחנת הרוח והבתים מספרים על חשש לצאת מן החומות ועל הצמיחה המהירה של העיר החדשה.\n\n\n\nעין כרם — כפר עתיק ושכונה מודרנית: עין כרם שומרת אופי כפרי בתוך ירושלים. המעיין והכנסיות קושרים מים, מסורת ואדריכלות. מסיימים מוקדם כדי לא להיתקע בעומסי ערב.\n\n\n\nפרופיל הדרך המשוער: 20% כביש מהיר או בין־עירוני, 10% כביש מפותל, 20% כביש אזורי ו־50% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
