      "story_big": "יום במדבר שבו דתות, אימפריות ומים נפגשים: תצפית על ואדי קלט, מסורת מוסלמית, אתר טבילה נוצרי ומגילות מדבר יהודה.\n\nהטיול מתחיל ב־מצפה יריחו, עובר דרך צפון מדבר יהודה ויריחו ומסתיים ב־קומראן. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nמצפה יריחו — התיישבות מודרנית מול דרך עתיקה: התצפית ממחישה את הירידה החדה מירושלים לבקעת הירדן. דרך זו שימשה מסחר, צבא ועלייה לרגל לאורך אלפי שנים.\n\n\n\nנבי מוסא — המבנה התפתח מן המאה ה־13: לפי המסורת המוסלמית המקומית, נבי מוסא הוא מקום קבורת משה. המתחם התפתח בתקופה הממלוכית והעות׳מאנית ושימש מוקד עלייה לרגל.\n\n\n\nקאסר אל־יהוד — מסורות נוצריות; אתר גבול מודרני: המקום מזוהה במסורת הנוצרית עם טבילת ישו ובמסורת יהודית עם חציית הירדן. הביקור כפוף להוראות אתר גבול; אין להתייחס אליו כחוף רחצה חופשי.\n\n\n\nגן לאומי קומראן — המאה השנייה לפנה״ס עד 68 לספירה: מגילות קומראן התגלו משנת 1947 ואילך במערות הסמוכות. הן כוללות כתבי מקרא וטקסטים קהילתיים ומאפשרות הצצה לעולם היהודי לפני חורבן הבית השני.\n\n\n\nצומת קליה — נקודת דרך מודרנית: במדבר עייפות והתייבשות מתפתחות בלי לשים לב. עוצרים, שותים, בודקים לחץ אוויר ומחליטים אם ממשיכים או חוזרים במסלול הקצר.\n\n\n\nפרופיל הדרך המשוער: 50% כביש מהיר או בין־עירוני, 15% כביש מפותל, 25% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
