      "springs": [],
      "story_big": "טיול יום נינוח לאורך רכס הכורכר: מבצר צלבני, מצוקים, שמורות חוף, נחל ושפך לים.\n\nהטיול מתחיל ב־הרצליה, עובר דרך חוף השרון ומסתיים ב־מכמורת. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nגן לאומי אפולוניה — התקופה הצלבנית; נכבש ב־1265: אפולוניה הייתה עיר נמל קדומה ומבצר צלבני. ב־1265 כבש אותה ביברס. המצוק מסביר את יתרון ההגנה וגם את סכנת ההתמוטטות, ולכן נשארים בשביל.\n\n\n\nגן לאומי חוף השרון — רכס כורכר וחולות: רכס הכורכר נוצר מחול שהתלכד. גלי הים והרוח ממשיכים לשחוק אותו, ולכן קו המצוק משתנה. זו עצירה שממחישה גאולוגיה בתנועה.\n\n\n\nגעש — יישוב חוף מודרני: עוצרים במקום מותר ולא על דרך חקלאית. המטרה היא קפה, שירותים וספירת הקבוצה לפני הקטע העירוני של נתניה.\n\n\n\nשמורת נחל פולג — מפעל ניקוז עתיק ומודרני: הפרצה ברכס פולג קשורה לניקוז הביצות ממזרח. הנחל וסביבתו מספרים כיצד האדם משנה מערכות מים כדי להכשיר קרקע.\n\n\n\nמכמורת ונחל אלכסנדר — נמל קטן והתיישבות מודרנית: נחל אלכסנדר קיבל את שמו המודרני בתקופת המנדט. השפך הוא בית גידול רגיש. רחצה רק בחוף מוכרז ובשעות הצלה.\n\n\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 10% כביש מפותל, 30% כביש אזורי ו־25% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
