      "springs": [],
      "story_big": "טיול על הנדסת מים: סכר רומי, אמות שהובילו מים לעיר נמל, תיאטרון ותחנת תרבות בשוני.\n\nהטיול מתחיל ב־נחל תנינים, עובר דרך חוף הכרמל ודרום הכרמל ומסתיים ב־זכרון יעקב. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nשמורת טבע נחל תנינים — התקופה הרומית והביזנטית: הרומאים והביזנטים ניצלו את מי הנחל והביצות כדי להזין אמות לקיסריה. הסכר ממחיש הנדסה בקנה מידה גדול, אך המערכת היא גם בית גידול רגיש.\n\n\n\nאמת המים הגבוהה לקיסריה — המאה הראשונה לספירה ואילך: קיסריה גדלה מעבר ליכולת הבארות המקומיות. האמה ניצלה שיפוע מתון מאוד כדי להעביר מים למרחק רב. זו הזדמנות להסביר שמים זורמים בלי משאבה כאשר התכנון מדויק.\n\n\n\nגן לאומי קיסריה — הורדוס, סוף המאה הראשונה לפנה״ס: הורדוס בנה בקיסריה נמל ענק באמצעות בטון הידראולי. העיר נקראה לכבוד אוגוסטוס והפכה לבירת הפרובינקיה הרומית בארץ.\n\n\n\nפארק ז׳בוטינסקי שוני — התקופה הרומית; תקופת המנדט: שוני שימשה אתר בילוי רומי ובהמשך בסיס אימונים של האצ״ל. השילוב בין תיאטרון, מים ומחתרת מראה כיצד אותו מקום מקבל שימושים שונים.\n\n\n\nזכרון יעקב — 1882 ואילך: זכרון יעקב היא ממושבות העלייה הראשונה. תמיכת הברון רוטשילד, חקלאות הכרמים ורשת ניל״י הופכים אותה לסיום עתיר סיפורים ואוכל.\n\n\n\nפרופיל הדרך המשוער: 30% כביש מהיר או בין־עירוני, 20% כביש מפותל, 30% כביש אזורי ו־20% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
