      "story_big": "מסלול מים־יבשתי שעוקב מן השפלה אל הים: עיר מקראית, גשר רכבת עות׳מאני, גבעות כורכר ושדות נגב מערבי.\n\nהטיול מתחיל ב־תל לכיש, עובר דרך שפלת יהודה וצפון הנגב ומסתיים ב־זיקים. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nגן לאומי תל לכיש — 701 לפנה״ס: לכיש הייתה העיר השנייה בחשיבותה בממלכת יהודה. כיבוש סנחריב בשנת 701 לפנה״ס תועד בתבליטים אשוריים. מן התל רואים דרך, שער ומערכת מצור.\n\n\n\nתל נגילה וגשר הרכבת — 1917: העות׳מאנים בנו מסילות בנגב לצורכי הצבא במלחמת העולם הראשונה. הגשרים והסוללות מספרים על מאמץ לוגיסטי במדבר.\n\n\n\nדרך נוף נחל שקמה — פיתוח קק״ל מודרני: נחל שקמה מנקז את השפלה אל הים. הדרך מאפשרת לראות מעבר הדרגתי מאדמות גבעיות למישור חוף, אך היא אינה כביש מרוץ: אבק, בוץ וכלים חקלאיים הם חלק מן הסביבה.\n\n\n\nבתרונות רוחמה — גאולוגיה וחקלאות: הלס נחרץ בקלות בזרימת מים ויוצר בתרונות. בחורף ובאביב האזור פורח, אך גם רגיש מאוד לדריסה ולבוץ.\n\n\n\nחוף זיקים – רק אם פתוח — חוף גבול מודרני: החוף סמוך למרחב גבול ולכן פתיחתו אינה מובנת מאליה. אם אינו פתוח מסיימים באשקלון. רחצה רק בחוף מוכרז ובשעות מציל.\n\n\n\nפרופיל הדרך המשוער: 30% כביש מהיר או בין־עירוני, 10% כביש מפותל, 50% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
