      "springs": [],
      "story_big": "יום שמחבר קרב אנז״ק, גבול ההתקדמות המצרית ב־1948, מצודה מוסלמית על הים וסיפור הגבורה והמחלוקת של ניצנים.\n\nהטיול מתחיל ב־גשר עד הלום, עובר דרך מישור החוף הדרומי ומסתיים ב־חוף ניצנים. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nפארק עד הלום — 1917 ו־1948: ב־1917 עברו באזור כוחות בריטיים ואנז״ק. במאי 1948 נעצר כאן הכוח המצרי שהתקדם צפונה. השם “עד הלום” מסכם את נקודת הבלימה.\n\n\n\nמצודת אשדוד ים — המאות השביעית–האחת עשרה: המצודה הייתה חלק ממערך הגנה מפני פשיטות מן הים. מגדלים ומערכת איתות חיברו בין נקודות לאורך החוף.\n\n\n\nחוף המצודה — רכס כורכר וחולות: החול נודד והרוח מכסה כבישים ושבילים. האופנוע נשאר בחניה; לא מנסים “רק כמה מטרים” בחול עמוק.\n\n\n\nניצנים הישנה – בית ספר שדה — יוני 1948: ניצנים נפלה לאחר קרב קשה ביוני 1948. מגיני המקום ספגו ביקורת חריפה, ובהמשך נעשה תיקון היסטורי. הסיפור מזמין דיון באחריות, גבורה ושיפוט בדיעבד.\n\n\n\nחוף ניצנים — שמורת חולות וחוף: ניצנים משמרת רצף חולות חשוב. הרחצה רק באזור מוכרז, והאופנוע נשאר על משטח יציב. מסיימים לפני רדת החשכה.\n\n\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 5% כביש מפותל, 35% כביש אזורי ו־25% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
