      "springs": [],
      "story_big": "אחד מימי הכביש המבודדים בארץ: רמה גבוהה, בורות מים עתיקים, שמי מדבר וכביש שמסתיים סמוך למרחב גבול.\n\nהטיול מתחיל ב־מצפה רמון, עובר דרך הר הנגב הגבוה ומסתיים ב־מצפה רמון. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nמצפה רמון – תדריך מדבר — יישוב הר הנגב: במסלול בודד אין מקום ל“נסתדר”. בודקים לחץ אוויר, פנצ׳רייה, מים וטלפון. רוכב ללא טווח מספיק אינו יוצא.\n\n\n\nצומת הרוחות — הר הנגב: כאן התנועה מתמעטת והמרחב נפתח. הרוח יכולה להיות חזקה בהרבה מן התחושה במצפה רמון.\n\n\n\nבורות לוץ — חקלאות מדברית קדומה: בורות לוץ אוספים נגר עילי. המערכת מוכיחה שהמדבר אינו ריק: ידע בניקוז אפשר חקלאות והתיישבות. אין כניסה למים.\n\n\n\nהר רומם – אזור תצפית מותר — הר הנגב הגבוה: הגובה משנה טמפרטורה, צמחייה וראות. עוצרים רק ברחבה בטוחה; אין לעלות בדרך צבאית או לסטות לשטח.\n\n\n\nמצפה רמון — יישוב מדברי מודרני: החזרה באותו כביש אינה “אותו דבר”: השמש והצל משנים את קריאת הפניות. מסיימים בארוחה ובדיקת עייפות לפני הירידה צפונה.\n\n\n\nפרופיל הדרך המשוער: 35% כביש מהיר או בין־עירוני, 30% כביש מפותל, 30% כביש אזורי ו־5% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
