      "springs": [],
      "story_big": "טיול שמחבר ים סוף, מכרות נחושת עתיקים, תצורות אבן וחזון חקלאי בערבה.\n\nהטיול מתחיל ב־אילת, עובר דרך הערבה הדרומית ומסתיים ב־יטבתה. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nאילת – נקודת יציאה צפונית — עיר נמל מודרנית: יוצאים מוקדם כדי להימנע מחום ורוחות. בודקים שכל רוכב נושא לפחות שלושה ליטרים מים ביום קיץ גבולי.\n\n\n\nבאר אורה — היישוב המודרני מ־1950: באר אורה מזכירה את ניסיונות פיתוח הערבה לאחר קום המדינה ואת עבודת מכרות תמנע בתקופות שונות.\n\n\n\nפארק תמנע – מרכז המבקרים — כרייה מן האלף הרביעי לפנה״ס ובתקופות מצריות: בתמנע פעלו מכרות ומתקני התכה. משלחות מצריות הותירו מקדש וכתובות. הנוף נוצר מאבן חול צבעונית ושברים גאולוגיים.\n\n\n\nעמודי שלמה והפטרייה — גאולוגיה מדברית: הרוח והמים חותכים שכבות רכות ומשאירים קירות ועמודים. השמות מודרניים יחסית; התהליך גאולוגי ארוך. האופנוע נשאר בדרך ובחניה.\n\n\n\nיטבתה — קיבוץ מ־1957: יטבתה הוכיחה שניתן לקיים חקלאות ורפת במדבר באמצעות מים, אנרגיה ותכנון. זו עצירה נוחה לאוכל, תדלוק ומנוחה.\n\n\n\nפרופיל הדרך המשוער: 45% כביש מהיר או בין־עירוני, 10% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
