      "springs": [],
      "story_big": "טיול על החיים במדבר היום: אנרגיה סולארית, קהילה אקולוגית, אדריכלות יוצאת דופן וחקלאות בתנאי קיצון.\n\nהטיול מתחיל ב־קטורה, עובר דרך הערבה הדרומית ומסתיים ב־יטבתה. הוא נבנה כך שהרכיבה עצמה תהיה חלק מהסיפור: קטעי הקישור משמשים להתארגנות, ובכבישים המקומיים מורידים קצב כדי לקרוא את פני הכביש ואת הנוף.\n\nקיבוץ קטורה — נוסד ב־1973: קטורה משלבת חקלאות, תיירות ומחקר אנרגיה. באזור קודמו מתקנים סולאריים וניסויים המתאימים לשמש המדברית החזקה.\n\n\n\nקיבוץ לוטן — נוסד ב־1983: לוטן פיתחה מרכז אקולוגי העוסק בבנייה מחומרים מקומיים, קומפוסט ותכנון אקלימי. הביקור דורש תיאום, אך הסיפור מתאים גם בעצירה קצרה.\n\n\n\nנאות סמדר — נוסדה ב־1989: נאות סמדר הוקמה כקהילה המתמקדת בלמידה, חקלאות ואמנות. המבנה המרכזי משתמש בצל, רוח ומים כדי ליצור אקלים פנימי נעים יותר.\n\n\n\nחי־בר יטבתה – תצפית או ביקור — שמורת חי־בר מ־1968: חי־בר הוקם כדי לגדל ולהשיב מינים שנעלמו מן הארץ. סיפורי הפרא והראם מדגימים ששימור דורש שטח, זמן ומעקב.\n\n\n\nיטבתה — קיבוץ מ־1957: מסיימים בארוחה ובתדלוק. אחרי יום איטי בין קהילות, כביש 90 עלול להרגיש מונוטוני; מחליפים מוביל או עוצרים שוב אם יש עייפות.\n\n\n\nפרופיל הדרך המשוער: 50% כביש מהיר או בין־עירוני, 5% כביש מפותל, 35% כביש אזורי ו־10% קטע עירוני. זו הערכת תכנון בלבד ולא מדידת GPS. מסלול מגוון: קטעי קישור מהירים לצד כבישים אזוריים. בפניות עיוורות שומרים קו שמרני, מרווח גדול ויכולת עצירה בתוך שדה הראייה.",
